00121 #ifdef __ANDROID__
00122 // Implementation helpers of EnsureReadable(address).
00123 // This is so far only needed on Android, where it is common for libraries to be mapped
00124 // with only executable, not readable, permissions. Typical example (line from /proc/self/maps):
00125 /*
00126 746b63b000-746b6dc000 --xp 00042000 07:48 35                             /apex/com.android.runtime/lib64/bionic/libc.so
00127 */
00128 // See https://github.com/wolfpld/tracy/issues/125 .
00129 // To work around this, we parse /proc/self/maps and we use mprotect to set read permissions
00130 // on any mappings that contain symbols addresses hit by HandleSymbolCodeQuery.
00131 
00132 namespace {
00133 // Holds some information about a single memory mapping.
00134 struct MappingInfo {
00135     // Start of address range. Inclusive.
00136     uintptr_t start_address;
00137     // End of address range. Exclusive, so the mapping is the half-open interval
00138     // [start, end) and its length in bytes is `end - start`. As in /proc/self/maps.
00139     uintptr_t end_address;
00140     // Read/Write/Executable permissions.
00141     bool perm_r, perm_w, perm_x;
00142 };
00143 }  // anonymous namespace
00144 
00145    // Internal implementation helper for LookUpMapping(address).
00146    //
00147    // Parses /proc/self/maps returning a vector<MappingInfo>.
00148    // /proc/self/maps is assumed to be sorted by ascending address, so the resulting
00149    // vector is sorted by ascending address too.
00150 static std::vector<MappingInfo> ParseMappings()
00151 {
00152     std::vector<MappingInfo> result;
00153     FILE* file = fopen( "/proc/self/maps", "r" );
00154     if( !file ) return result;
00155     char line[1024];
00156     while( fgets( line, sizeof( line ), file ) )
00157     {
00158         uintptr_t start_addr;
00159         uintptr_t end_addr;
00160         if( sscanf( line, "%lx-%lx", &start_addr, &end_addr ) != 2 ) continue;
00161         char* first_space = strchr( line, ' ' );
00162         if( !first_space ) continue;
00163         char* perm = first_space + 1;
00164         char* second_space = strchr( perm, ' ' );
00165         if( !second_space || second_space - perm != 4 ) continue;
00166         result.emplace_back();
00167         auto& mapping = result.back();
00168         mapping.start_address = start_addr;
00169         mapping.end_address = end_addr;
00170         mapping.perm_r = perm[0] == 'r';
00171         mapping.perm_w = perm[1] == 'w';
00172         mapping.perm_x = perm[2] == 'x';
00173     }
00174     fclose( file );
00175     return result;
00176 }
00177 
00178 // Internal implementation helper for LookUpMapping(address).
00179 //
00180 // Takes as input an `address` and a known vector `mappings`, assumed to be
00181 // sorted by increasing addresses, as /proc/self/maps seems to be.
00182 // Returns a pointer to the MappingInfo describing the mapping that this
00183 // address belongs to, or nullptr if the address isn't in `mappings`.
00184 static MappingInfo* LookUpMapping(std::vector<MappingInfo>& mappings, uintptr_t address)
00185 {
00186     // Comparison function for std::lower_bound. Returns true if all addresses in `m1`
00187     // are lower than `addr`.
00188     auto Compare = []( const MappingInfo& m1, uintptr_t addr ) {
00189         // '<=' because the address ranges are half-open intervals, [start, end).
00190         return m1.end_address <= addr;
00191     };
00192     auto iter = std::lower_bound( mappings.begin(), mappings.end(), address, Compare );
00193     if( iter == mappings.end() || iter->start_address > address) {
00194         return nullptr;
00195     }
00196     return &*iter;
00197 }
00198 
00199 // Internal implementation helper for EnsureReadable(address).
00200 //
00201 // Takes as input an `address` and returns a pointer to a MappingInfo
00202 // describing the mapping that this address belongs to, or nullptr if
00203 // the address isn't in any known mapping.
00204 //
00205 // This function is stateful and not reentrant (assumes to be called from
00206 // only one thread). It holds a vector of mappings parsed from /proc/self/maps.
00207 //
00208 // Attempts to react to mappings changes by re-parsing /proc/self/maps.
00209 static MappingInfo* LookUpMapping(uintptr_t address)
00210 {
00211     // Static state managed by this function. Not constant, we mutate that state as
00212     // we turn some mappings readable. Initially parsed once here, updated as needed below.
00213     static std::vector<MappingInfo> s_mappings = ParseMappings();
00214     MappingInfo* mapping = LookUpMapping( s_mappings, address );
00215     if( mapping ) return mapping;
00216 
00217     // This address isn't in any known mapping. Try parsing again, maybe
00218     // mappings changed.
00219     s_mappings = ParseMappings();
00220     return LookUpMapping( s_mappings, address );
00221 }
00222 
00223 // Internal implementation helper for EnsureReadable(address).
00224 //
00225 // Attempts to make the specified `mapping` readable if it isn't already.
00226 // Returns true if and only if the mapping is readable.
00227 static bool EnsureReadable( MappingInfo& mapping )
00228 {
00229     if( mapping.perm_r )
00230     {
00231         // The mapping is already readable.
00232         return true;
00233     }
00234     int prot = PROT_READ;
00235     if( mapping.perm_w ) prot |= PROT_WRITE;
00236     if( mapping.perm_x ) prot |= PROT_EXEC;
00237     if( mprotect( reinterpret_cast<void*>( mapping.start_address ),
00238         mapping.end_address - mapping.start_address, prot ) == -1 )
00239     {
00240         // Failed to make the mapping readable. Shouldn't happen, hasn't
00241         // been observed yet. If it happened in practice, we should consider
00242         // adding a bool to MappingInfo to track this to avoid retrying mprotect
00243         // everytime on such mappings.
00244         return false;
00245     }
00246     // The mapping is now readable. Update `mapping` so the next call will be fast.
00247     mapping.perm_r = true;
00248     return true;
00249 }
00250 
00251 // Attempts to set the read permission on the entire mapping containing the
00252 // specified address. Returns true if and only if the mapping is now readable.
00253 static bool EnsureReadable( uintptr_t address )
00254 {
00255     MappingInfo* mapping = LookUpMapping(address);
00256     return mapping && EnsureReadable( *mapping );
00257 }
