00291 static void InitFailure( const char* msg )
00292 {
00293 #if defined _WIN32
00294     bool hasConsole = false;
00295     bool reopen = false;
00296     const auto attached = AttachConsole( ATTACH_PARENT_PROCESS );
00297     if( attached )
00298     {
00299         hasConsole = true;
00300         reopen = true;
00301     }
00302     else
00303     {
00304         const auto err = GetLastError();
00305         if( err == ERROR_ACCESS_DENIED )
00306         {
00307             hasConsole = true;
00308         }
00309     }
00310     if( hasConsole )
00311     {
00312         fprintf( stderr, "Tracy Profiler initialization failure: %s\n", msg );
00313         if( reopen )
00314         {
00315             freopen( "CONOUT$", "w", stderr );
00316             fprintf( stderr, "Tracy Profiler initialization failure: %s\n", msg );
00317         }
00318     }
00319     else
00320     {
00321 #  ifndef TRACY_UWP
00322         MessageBoxA( nullptr, msg, "Tracy Profiler initialization failure", MB_ICONSTOP );
00323 #  endif
00324     }
00325 #else
00326     fprintf( stderr, "Tracy Profiler initialization failure: %s\n", msg );
00327 #endif
00328     exit( 1 );
00329 }
