00331 static bool CheckHardwareSupportsInvariantTSC()
00332 {
00333     const char* noCheck = GetEnvVar( "TRACY_NO_INVARIANT_CHECK" );
00334     if( noCheck && noCheck[0] == '1' ) return true;
00335 
00336     uint32_t regs[4];
00337     CpuId( regs, 1 );
00338     if( !( regs[3] & ( 1 << 4 ) ) )
00339     {
00340 #if !defined TRACY_TIMER_QPC && !defined TRACY_TIMER_FALLBACK
00341         InitFailure( "CPU doesn't support RDTSC instruction." );
00342 #else
00343         return false;
00344 #endif
00345     }
00346     CpuId( regs, 0x80000007 );
00347     if( regs[3] & ( 1 << 8 ) ) return true;
00348 
00349     return false;
00350 }
00351 
00352 #if defined TRACY_TIMER_FALLBACK && defined TRACY_HW_TIMER
00353 bool HardwareSupportsInvariantTSC()
