00382 static const char* GetProcessName()
00383 {
00384     const char* processName = "unknown";
00385 #ifdef _WIN32
00386     static char buf[_MAX_PATH];
00387     GetModuleFileNameA( nullptr, buf, _MAX_PATH );
00388     const char* ptr = buf;
00389     while( *ptr != '\0' ) ptr++;
00390     while( ptr > buf && *ptr != '\\' && *ptr != '/' ) ptr--;
00391     if( ptr > buf ) ptr++;
00392     processName = ptr;
00393 #elif defined __ANDROID__
00394 #  if __ANDROID_API__ >= 21
00395     auto buf = getprogname();
00396     if( buf ) processName = buf;
00397 #  endif
00398 #elif defined __linux__ && defined _GNU_SOURCE
00399     if( program_invocation_short_name ) processName = program_invocation_short_name;
00400 #elif defined __APPLE__ || defined BSD
00401     auto buf = getprogname();
00402     if( buf ) processName = buf;
00403 #endif
00404     return processName;
00405 }
