00585 #if defined __i386 || defined _M_IX86 || defined __x86_64__ || defined _M_X64
00586     uint32_t regs[4];
00587     char cpuModel[4*4*3+1] = {};
00588     auto modelPtr = cpuModel;
00589     for( uint32_t i=0x80000002; i<0x80000005; ++i )
00590     {
00591         CpuId( regs, i );
00592         memcpy( modelPtr, regs, sizeof( regs ) ); modelPtr += sizeof( regs );
00593     }
