00595     ptr += sprintf( ptr, "CPU: %s\n", cpuModel );
00596 #elif defined __linux__ && defined __ARM_ARCH
00597     bool cpuFound = false;
00598     FILE* fcpuinfo = fopen( "/proc/cpuinfo", "rb" );
00599     if( fcpuinfo )
00600     {
00601         enum { BufSize = 4*1024 };
00602         char buf[BufSize];
00603         const auto sz = fread( buf, 1, BufSize, fcpuinfo );
00604         fclose( fcpuinfo );
00605         const auto end = buf + sz;
00606         auto cptr = buf;
00607 
00608         uint32_t impl = 0;
00609         uint32_t var = 0;
00610         uint32_t part = 0;
00611         uint32_t rev = 0;
00612 
00613         while( end - cptr > 20 )
00614         {
00615             while( end - cptr > 20 && memcmp( cptr, "CPU ", 4 ) != 0 )
00616             {
00617                 cptr += 4;
00618                 while( end - cptr > 20 && *cptr != '\n' ) cptr++;
00619                 cptr++;
00620             }
00621             if( end - cptr <= 20 ) break;
00622             cptr += 4;
00623             if( memcmp( cptr, "implementer\t: ", 14 ) == 0 )
00624             {
00625                 if( impl != 0 ) break;
00626                 impl = GetHex( cptr, 14 );
00627             }
00628             else if( memcmp( cptr, "variant\t: ", 10 ) == 0 ) var = GetHex( cptr, 10 );
00629             else if( memcmp( cptr, "part\t: ", 7 ) == 0 ) part = GetHex( cptr, 7 );
00630             else if( memcmp( cptr, "revision\t: ", 11 ) == 0 ) rev = GetHex( cptr, 11 );
00631             while( *cptr != '\n' && *cptr != '\0' ) cptr++;
00632             cptr++;
00633         }
00634 
00635         if( impl != 0 || var != 0 || part != 0 || rev != 0 )
00636         {
00637             cpuFound = true;
00638             ptr += sprintf( ptr, "CPU: %s%s r%ip%i\n", DecodeArmImplementer( impl ), DecodeArmPart( impl, part ), var, rev );
00639         }
00640     }
00641     if( !cpuFound )
00642     {
00643         ptr += sprintf( ptr, "CPU: unknown\n" );
00644     }
00645 #elif defined __APPLE__ && TARGET_OS_IPHONE == 1
00646     {
00647         size_t sz;
00648         sysctlbyname( "hw.machine", nullptr, &sz, nullptr, 0 );
00649         auto str = (char*)tracy_malloc( sz );
00650         sysctlbyname( "hw.machine", str, &sz, nullptr, 0 );
00651         ptr += sprintf( ptr, "Device: %s\n", DecodeIosDevice( str ) );
00652         tracy_free( str );
00653     }
00654 #else
00655     ptr += sprintf( ptr, "CPU: unknown\n" );
00656 #endif
00657 #ifdef __ANDROID__
00658     char deviceModel[PROP_VALUE_MAX+1];
00659     char deviceManufacturer[PROP_VALUE_MAX+1];
00660     __system_property_get( "ro.product.model", deviceModel );
00661     __system_property_get( "ro.product.manufacturer", deviceManufacturer );
00662     ptr += sprintf( ptr, "Device: %s %s\n", deviceManufacturer, deviceModel );
00663 #endif
00664 
00665     ptr += sprintf( ptr, "CPU cores: %i\n", std::thread::hardware_concurrency() );
00666 
00667 #if defined _WIN32
00668     MEMORYSTATUSEX statex;
00669     statex.dwLength = sizeof( statex );
00670     GlobalMemoryStatusEx( &statex );
00671 #  ifdef _MSC_VER
00672     ptr += sprintf( ptr, "RAM: %I64u MB\n", statex.ullTotalPhys / 1024 / 1024 );
00673 #  else
00674     ptr += sprintf( ptr, "RAM: %llu MB\n", statex.ullTotalPhys / 1024 / 1024 );
00675 #  endif
00676 #elif defined __linux__
00677     struct sysinfo sysInfo;
00678     sysinfo( &sysInfo );
00679     ptr += sprintf( ptr, "RAM: %lu MB\n", sysInfo.totalram / 1024 / 1024 );
00680 #elif defined __APPLE__
00681     size_t memSize;
00682     size_t sz = sizeof( memSize );
00683     sysctlbyname( "hw.memsize", &memSize, &sz, nullptr, 0 );
00684     ptr += sprintf( ptr, "RAM: %zu MB\n", memSize / 1024 / 1024 );
00685 #elif defined BSD
00686     size_t memSize;
00687     size_t sz = sizeof( memSize );
00688     sysctlbyname( "hw.physmem", &memSize, &sz, nullptr, 0 );
00689     ptr += sprintf( ptr, "RAM: %zu MB\n", memSize / 1024 / 1024 );
00690 #else
00691     ptr += sprintf( ptr, "RAM: unknown\n" );
00692 #endif
00693 
00694     return buf;
00695 }
