00738 #if defined _WIN32 && !defined TRACY_UWP && !defined TRACY_NO_CRASH_HANDLER
00739 static DWORD s_profilerThreadId = 0;
00740 static DWORD s_symbolThreadId = 0;
00741 static char s_crashText[1024];
00742 
00743 LONG WINAPI CrashFilter( PEXCEPTION_POINTERS pExp )
00744 {
00745     if( !GetProfiler().IsConnected() ) return EXCEPTION_CONTINUE_SEARCH;
00746 
00747     const unsigned ec = pExp->ExceptionRecord->ExceptionCode;
00748     auto msgPtr = s_crashText;
00749     switch( ec )
00750     {
00751     case EXCEPTION_ACCESS_VIOLATION:
00752         msgPtr += sprintf( msgPtr, "Exception EXCEPTION_ACCESS_VIOLATION (0x%x). ", ec );
00753         switch( pExp->ExceptionRecord->ExceptionInformation[0] )
00754         {
00755         case 0:
00756             msgPtr += sprintf( msgPtr, "Read violation at address 0x%" PRIxPTR ".", pExp->ExceptionRecord->ExceptionInformation[1] );
00757             break;
00758         case 1:
00759             msgPtr += sprintf( msgPtr, "Write violation at address 0x%" PRIxPTR ".", pExp->ExceptionRecord->ExceptionInformation[1] );
00760             break;
00761         case 8:
00762             msgPtr += sprintf( msgPtr, "DEP violation at address 0x%" PRIxPTR ".", pExp->ExceptionRecord->ExceptionInformation[1] );
00763             break;
00764         default:
00765             break;
00766         }
00767         break;
00768     case EXCEPTION_ARRAY_BOUNDS_EXCEEDED:
00769         msgPtr += sprintf( msgPtr, "Exception EXCEPTION_ARRAY_BOUNDS_EXCEEDED (0x%x). ", ec );
00770         break;
00771     case EXCEPTION_DATATYPE_MISALIGNMENT:
00772         msgPtr += sprintf( msgPtr, "Exception EXCEPTION_DATATYPE_MISALIGNMENT (0x%x). ", ec );
00773         break;
00774     case EXCEPTION_FLT_DIVIDE_BY_ZERO:
00775         msgPtr += sprintf( msgPtr, "Exception EXCEPTION_FLT_DIVIDE_BY_ZERO (0x%x). ", ec );
00776         break;
00777     case EXCEPTION_ILLEGAL_INSTRUCTION:
00778         msgPtr += sprintf( msgPtr, "Exception EXCEPTION_ILLEGAL_INSTRUCTION (0x%x). ", ec );
00779         break;
00780     case EXCEPTION_IN_PAGE_ERROR:
00781         msgPtr += sprintf( msgPtr, "Exception EXCEPTION_IN_PAGE_ERROR (0x%x). ", ec );
00782         break;
00783     case EXCEPTION_INT_DIVIDE_BY_ZERO:
00784         msgPtr += sprintf( msgPtr, "Exception EXCEPTION_INT_DIVIDE_BY_ZERO (0x%x). ", ec );
00785         break;
00786     case EXCEPTION_PRIV_INSTRUCTION:
00787         msgPtr += sprintf( msgPtr, "Exception EXCEPTION_PRIV_INSTRUCTION (0x%x). ", ec );
00788         break;
00789     case EXCEPTION_STACK_OVERFLOW:
00790         msgPtr += sprintf( msgPtr, "Exception EXCEPTION_STACK_OVERFLOW (0x%x). ", ec );
00791         break;
00792     default:
00793         return EXCEPTION_CONTINUE_SEARCH;
00794     }
00795 
00796     {
00797         GetProfiler().SendCallstack( 60, "KiUserExceptionDispatcher" );
00798 
00799         TracyQueuePrepare( QueueType::CrashReport );
00800         item->crashReport.time = Profiler::GetTime();
00801         item->crashReport.text = (uint64_t)s_crashText;
00802         TracyQueueCommit( crashReportThread );
00803     }
00804 
00805     HANDLE h = CreateToolhelp32Snapshot( TH32CS_SNAPTHREAD, 0 );
00806     if( h == INVALID_HANDLE_VALUE ) return EXCEPTION_CONTINUE_SEARCH;
00807 
00808     THREADENTRY32 te = { sizeof( te ) };
00809     if( !Thread32First( h, &te ) )
00810     {
00811         CloseHandle( h );
00812         return EXCEPTION_CONTINUE_SEARCH;
00813     }
00814 
00815     const auto pid = GetCurrentProcessId();
00816     const auto tid = GetCurrentThreadId();
00817 
00818     do
00819     {
00820         if( te.th32OwnerProcessID == pid && te.th32ThreadID != tid && te.th32ThreadID != s_profilerThreadId && te.th32ThreadID != s_symbolThreadId )
00821         {
00822             HANDLE th = OpenThread( THREAD_SUSPEND_RESUME, FALSE, te.th32ThreadID );
00823             if( th != INVALID_HANDLE_VALUE )
00824             {
00825                 SuspendThread( th );
00826                 CloseHandle( th );
00827             }
00828         }
00829     }
00830     while( Thread32Next( h, &te ) );
00831     CloseHandle( h );
00832 
00833     {
00834         TracyLfqPrepare( QueueType::Crash );
00835         TracyLfqCommit;
00836     }
00837 
00838     std::this_thread::sleep_for( std::chrono::milliseconds( 500 ) );
00839     GetProfiler().RequestShutdown();
00840     while( !GetProfiler().HasShutdownFinished() ) { std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) ); };
00841 
00842     return EXCEPTION_CONTINUE_SEARCH;
00843 }
00844 #endif
