00900 static void CrashHandler( int signal, siginfo_t* info, void* /*ucontext*/ )
00901 {
00902     bool expected = false;
00903     if( !s_alreadyCrashed.compare_exchange_strong( expected, true ) ) ThreadFreezer( signal );
00904 
00905     struct sigaction act = {};
00906     act.sa_handler = SIG_DFL;
00907     sigaction( SIGABRT, &act, nullptr );
00908 
00909     auto msgPtr = s_crashText;
00910     switch( signal )
00911     {
00912     case SIGILL:
00913         strcpy( msgPtr, "Illegal Instruction.\n" );
00914         while( *msgPtr ) msgPtr++;
00915         switch( info->si_code )
00916         {
00917         case ILL_ILLOPC:
00918             strcpy( msgPtr, "Illegal opcode.\n" );
00919             break;
00920         case ILL_ILLOPN:
00921             strcpy( msgPtr, "Illegal operand.\n" );
00922             break;
00923         case ILL_ILLADR:
00924             strcpy( msgPtr, "Illegal addressing mode.\n" );
00925             break;
00926         case ILL_ILLTRP:
00927             strcpy( msgPtr, "Illegal trap.\n" );
00928             break;
00929         case ILL_PRVOPC:
00930             strcpy( msgPtr, "Privileged opcode.\n" );
00931             break;
00932         case ILL_PRVREG:
00933             strcpy( msgPtr, "Privileged register.\n" );
00934             break;
00935         case ILL_COPROC:
00936             strcpy( msgPtr, "Coprocessor error.\n" );
00937             break;
00938         case ILL_BADSTK:
00939             strcpy( msgPtr, "Internal stack error.\n" );
00940             break;
00941         default:
00942             break;
00943         }
00944         break;
00945     case SIGFPE:
00946         strcpy( msgPtr, "Floating-point exception.\n" );
00947         while( *msgPtr ) msgPtr++;
00948         switch( info->si_code )
00949         {
00950         case FPE_INTDIV:
00951             strcpy( msgPtr, "Integer divide by zero.\n" );
00952             break;
00953         case FPE_INTOVF:
00954             strcpy( msgPtr, "Integer overflow.\n" );
00955             break;
00956         case FPE_FLTDIV:
00957             strcpy( msgPtr, "Floating-point divide by zero.\n" );
00958             break;
00959         case FPE_FLTOVF:
00960             strcpy( msgPtr, "Floating-point overflow.\n" );
00961             break;
00962         case FPE_FLTUND:
00963             strcpy( msgPtr, "Floating-point underflow.\n" );
00964             break;
00965         case FPE_FLTRES:
00966             strcpy( msgPtr, "Floating-point inexact result.\n" );
00967             break;
00968         case FPE_FLTINV:
00969             strcpy( msgPtr, "Floating-point invalid operation.\n" );
00970             break;
00971         case FPE_FLTSUB:
00972             strcpy( msgPtr, "Subscript out of range.\n" );
00973             break;
00974         default:
00975             break;
00976         }
00977         break;
00978     case SIGSEGV:
00979         strcpy( msgPtr, "Invalid memory reference.\n" );
00980         while( *msgPtr ) msgPtr++;
00981         switch( info->si_code )
00982         {
00983         case SEGV_MAPERR:
00984             strcpy( msgPtr, "Address not mapped to object.\n" );
00985             break;
00986         case SEGV_ACCERR:
00987             strcpy( msgPtr, "Invalid permissions for mapped object.\n" );
00988             break;
00989 #  ifdef SEGV_BNDERR
00990         case SEGV_BNDERR:
00991             strcpy( msgPtr, "Failed address bound checks.\n" );
00992             break;
00993 #  endif
00994 #  ifdef SEGV_PKUERR
00995         case SEGV_PKUERR:
00996             strcpy( msgPtr, "Access was denied by memory protection keys.\n" );
00997             break;
00998 #  endif
00999         default:
01000             break;
01001         }
01002         break;
01003     case SIGPIPE:
01004         strcpy( msgPtr, "Broken pipe.\n" );
01005         while( *msgPtr ) msgPtr++;
01006         break;
01007     case SIGBUS:
01008         strcpy( msgPtr, "Bus error.\n" );
01009         while( *msgPtr ) msgPtr++;
01010         switch( info->si_code )
01011         {
01012         case BUS_ADRALN:
01013             strcpy( msgPtr, "Invalid address alignment.\n" );
01014             break;
01015         case BUS_ADRERR:
01016             strcpy( msgPtr, "Nonexistent physical address.\n" );
01017             break;
01018         case BUS_OBJERR:
01019             strcpy( msgPtr, "Object-specific hardware error.\n" );
01020             break;
01021 #  ifdef BUS_MCEERR_AR
01022         case BUS_MCEERR_AR:
01023             strcpy( msgPtr, "Hardware memory error consumed on a machine check; action required.\n" );
01024             break;
01025 #  endif
01026 #  ifdef BUS_MCEERR_AO
01027         case BUS_MCEERR_AO:
01028             strcpy( msgPtr, "Hardware memory error detected in process but not consumed; action optional.\n" );
01029             break;
01030 #  endif
01031         default:
01032             break;
01033         }
01034         break;
01035     case SIGABRT:
01036         strcpy( msgPtr, "Abort signal from abort().\n" );
01037         break;
01038     default:
01039         abort();
01040     }
01041     while( *msgPtr ) msgPtr++;
01042 
01043     if( signal != SIGPIPE )
01044     {
01045         strcpy( msgPtr, "Fault address: 0x" );
01046         while( *msgPtr ) msgPtr++;
01047         HexPrint( msgPtr, uint64_t( info->si_addr ) );
01048         *msgPtr++ = '\n';
01049     }
01050 
01051     {
01052         GetProfiler().SendCallstack( 60, "__kernel_rt_sigreturn" );
01053 
01054         TracyQueuePrepare( QueueType::CrashReport );
01055         item->crashReport.time = Profiler::GetTime();
01056         item->crashReport.text = (uint64_t)s_crashText;
01057         TracyQueueCommit( crashReportThread );
01058     }
01059 
01060     DIR* dp = opendir( "/proc/self/task" );
01061     if( !dp ) abort();
01062 
01063     const auto selfTid = syscall( SYS_gettid );
01064 
01065     struct dirent* ep;
01066     while( ( ep = readdir( dp ) ) != nullptr )
01067     {
01068         if( ep->d_name[0] == '.' ) continue;
01069         int tid = atoi( ep->d_name );
01070         if( tid != selfTid && tid != s_profilerTid && tid != s_symbolTid )
01071         {
01072             syscall( SYS_tkill, tid, TRACY_CRASH_SIGNAL );
01073         }
01074     }
01075     closedir( dp );
01076 
01077 #ifdef TRACY_HAS_CALLSTACK
01078     if( selfTid == s_symbolTid ) s_symbolThreadGone.store( true, std::memory_order_release );
01079 #endif
01080 
01081     TracyLfqPrepare( QueueType::Crash );
01082     TracyLfqCommit;
01083 
01084     std::this_thread::sleep_for( std::chrono::milliseconds( 500 ) );
01085     GetProfiler().RequestShutdown();
01086     while( !GetProfiler().HasShutdownFinished() ) { std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) ); };
01087 
01088     abort();
01089 }
01090 #endif
