01190 // GCC prior to 8.4 had a bug with function-inline thread_local variables. Versions of glibc beginning with
01191 // 2.18 may attempt to work around this issue, which manifests as a crash while running static destructors
01192 // if this function is compiled into a shared object. Unfortunately, centos7 ships with glibc 2.17. If running
01193 // on old GCC, use the old-fashioned way as a workaround
01194 // See: https://gcc.gnu.org/bugzilla/show_bug.cgi?id=85400
01195 #if !defined(__clang__) && defined(__GNUC__) && ((__GNUC__ < 8) || ((__GNUC__ == 8) && (__GNUC_MINOR__ < 4)))
01196 struct ProfilerThreadDataKey
01197 {
01198 public:
01199     ProfilerThreadDataKey()
01200     {
01201         int val = pthread_key_create(&m_key, sDestructor);
01202         static_cast<void>(val); // unused
01203         assert(val == 0);
01204     }
01205     ~ProfilerThreadDataKey()
01206     {
01207         int val = pthread_key_delete(m_key);
01208         static_cast<void>(val); // unused
01209         assert(val == 0);
01210     }
01211     ProfilerThreadData& get()
01212     {
01213         void* p = pthread_getspecific(m_key);
01214         if (!p)
01215         {
01216             p = (ProfilerThreadData*)tracy_malloc( sizeof( ProfilerThreadData ) );
01217             new (p) ProfilerThreadData(GetProfilerData());
01218             pthread_setspecific(m_key, p);
01219         }
01220         return *static_cast<ProfilerThreadData*>(p);
01221     }
01222 private:
01223     pthread_key_t m_key;
01224 
01225     static void sDestructor(void* p)
01226     {
01227         ((ProfilerThreadData*)p)->~ProfilerThreadData();
01228         tracy_free(p);
01229     }
01230 };
