01272 
01273 // 2. If these variables would be in the .CRT$XCB section, they would be initialized only in main thread.
01274 thread_local moodycamel::ProducerToken init_order(107) s_token_detail( s_queue );
01275 thread_local ProducerWrapper init_order(108) s_token { s_queue.get_explicit_producer( s_token_detail ) };
