01286 std::atomic<int> init_order(102) RpInitLock( 0 );
01287 thread_local bool RpThreadInitDone = false;
01288 thread_local bool RpThreadShutdown = false;
01289 moodycamel::ConcurrentQueue<QueueItem> init_order(103) s_queue( QueuePrealloc );
01290 std::atomic<uint32_t> init_order(104) s_lockCounter( 0 );
01291 std::atomic<uint8_t> init_order(104) s_gpuCtxCounter( 0 );
