01397 void Profiler::SpawnWorkerThreads()
01398 {
01399 #ifdef TRACY_HAS_SYSTEM_TRACING
01400     if( SysTraceStart( m_samplingPeriod ) )
01401     {
01402         s_sysTraceThread = (Thread*)tracy_malloc( sizeof( Thread ) );
01403         new(s_sysTraceThread) Thread( SysTraceWorker, nullptr );
01404         std::this_thread::sleep_for( std::chrono::milliseconds( 1 ) );
01405     }
01406 #endif
01407 
01408     s_thread = (Thread*)tracy_malloc( sizeof( Thread ) );
01409     new(s_thread) Thread( LaunchWorker, this );
01410 
01411 #ifndef TRACY_NO_FRAME_IMAGE
01412     s_compressThread = (Thread*)tracy_malloc( sizeof( Thread ) );
01413     new(s_compressThread) Thread( LaunchCompressWorker, this );
01414 #endif
01415 
01416 #ifdef TRACY_HAS_CALLSTACK
01417     s_symbolThread = (Thread*)tracy_malloc( sizeof( Thread ) );
01418     new(s_symbolThread) Thread( LaunchSymbolWorker, this );
01419 #endif
01420 
01421 #if defined _WIN32 && !defined TRACY_UWP && !defined TRACY_NO_CRASH_HANDLER
01422     s_profilerThreadId = GetThreadId( s_thread->Handle() );
01423 #  ifdef TRACY_HAS_CALLSTACK
01424     s_symbolThreadId = GetThreadId( s_symbolThread->Handle() );
01425 #  endif
01426     m_exceptionHandler = AddVectoredExceptionHandler( 1, CrashFilter );
