01429 #if defined __linux__ && !defined TRACY_NO_CRASH_HANDLER
01430     struct sigaction threadFreezer = {};
01431     threadFreezer.sa_handler = ThreadFreezer;
01432     sigaction( TRACY_CRASH_SIGNAL, &threadFreezer, &m_prevSignal.pwr );
01433 
01434     struct sigaction crashHandler = {};
01435     crashHandler.sa_sigaction = CrashHandler;
01436     crashHandler.sa_flags = SA_SIGINFO;
01437     sigaction( SIGILL, &crashHandler, &m_prevSignal.ill );
01438     sigaction( SIGFPE, &crashHandler, &m_prevSignal.fpe );
01439     sigaction( SIGSEGV, &crashHandler, &m_prevSignal.segv );
01440     sigaction( SIGPIPE, &crashHandler, &m_prevSignal.pipe );
01441     sigaction( SIGBUS, &crashHandler, &m_prevSignal.bus );
01442     sigaction( SIGABRT, &crashHandler, &m_prevSignal.abrt );
01443 #endif
01444 
01445 #ifndef TRACY_NO_CRASH_HANDLER
01446     m_crashHandlerInstalled = true;
01447 #endif
01448 
01449 #ifdef TRACY_HAS_CALLSTACK
01450     InitCallstackCritical();
01451 #endif
01452 
01453     m_timeBegin.store( GetTime(), std::memory_order_relaxed );
01454 }
