01527 
01528 void Profiler::Worker()
01529 {
01530 #if defined __linux__ && !defined TRACY_NO_CRASH_HANDLER
01531     s_profilerTid = syscall( SYS_gettid );
01532 #endif
01533 
01534     ThreadExitHandler threadExitHandler;
01535 
01536     SetThreadName( "Tracy Profiler" );
01537 
01538 #ifdef TRACY_DATA_PORT
01539     const bool dataPortSearch = false;
01540     auto dataPort = m_userPort != 0 ? m_userPort : TRACY_DATA_PORT;
01541 #else
01542     const bool dataPortSearch = m_userPort == 0;
01543     auto dataPort = m_userPort != 0 ? m_userPort : 8086;
01544 #endif
01545 #ifdef TRACY_BROADCAST_PORT
01546     const auto broadcastPort = TRACY_BROADCAST_PORT;
01547 #else
01548     const auto broadcastPort = 8086;
01549 #endif
01550 
01551     while( m_timeBegin.load( std::memory_order_relaxed ) == 0 ) std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) );
01552 
01553 #ifdef TRACY_USE_RPMALLOC
01554     rpmalloc_thread_initialize();
01555 #endif
01556 
01557     m_exectime = 0;
01558     const auto execname = GetProcessExecutablePath();
01559     if( execname )
01560     {
01561         struct stat st;
01562         if( stat( execname, &st ) == 0 )
01563         {
01564             m_exectime = (uint64_t)st.st_mtime;
01565         }
01566     }
01567 
01568     const auto procname = GetProcessName();
01569     const auto pnsz = std::min<size_t>( strlen( procname ), WelcomeMessageProgramNameSize - 1 );
01570 
01571     const auto hostinfo = GetHostInfo();
01572     const auto hisz = std::min<size_t>( strlen( hostinfo ), WelcomeMessageHostInfoSize - 1 );
01573 
01574     const uint64_t pid = GetPid();
01575 
01576     uint8_t flags = 0;
01577 
01578 #ifdef TRACY_ON_DEMAND
01579     flags |= WelcomeFlag::OnDemand;
01580 #endif
01581 #ifdef __APPLE__
01582     flags |= WelcomeFlag::IsApple;
01583 #endif
01584 #ifndef TRACY_NO_CODE_TRANSFER
01585     flags |= WelcomeFlag::CodeTransfer;
01586 #endif
01587 #ifdef _WIN32
01588     flags |= WelcomeFlag::CombineSamples;
01589 #  ifndef TRACY_NO_CONTEXT_SWITCH
01590     flags |= WelcomeFlag::IdentifySamples;
01591 #  endif
01592 #endif
01593 
01594 #if defined __i386 || defined _M_IX86
01595     uint8_t cpuArch = CpuArchX86;
01596 #elif defined __x86_64__ || defined _M_X64
01597     uint8_t cpuArch = CpuArchX64;
01598 #elif defined __aarch64__
01599     uint8_t cpuArch = CpuArchArm64;
01600 #elif defined __ARM_ARCH
01601     uint8_t cpuArch = CpuArchArm32;
01602 #else
01603     uint8_t cpuArch = CpuArchUnknown;
01604 #endif
01605 
01606 #if defined __i386 || defined _M_IX86 || defined __x86_64__ || defined _M_X64
01607     uint32_t regs[4];
01608     char manufacturer[12];
01609     CpuId( regs, 0 );
01610     memcpy( manufacturer, regs+1, 4 );
01611     memcpy( manufacturer+4, regs+3, 4 );
01612     memcpy( manufacturer+8, regs+2, 4 );
01613 
01614     CpuId( regs, 1 );
01615     uint32_t cpuId = ( regs[0] & 0xFFF ) | ( ( regs[0] & 0xFFF0000 ) >> 4 );
01616 #else
01617     const char manufacturer[12] = {};
01618     uint32_t cpuId = 0;
01619 #endif
01620 
01621     WelcomeMessage welcome;
01622     MemWrite( &welcome.timerMul, m_timerMul );
01623     MemWrite( &welcome.initBegin, GetInitTime() );
01624     MemWrite( &welcome.initEnd, m_timeBegin.load( std::memory_order_relaxed ) );
01625     MemWrite( &welcome.delay, m_delay );
01626     MemWrite( &welcome.resolution, m_resolution );
01627     MemWrite( &welcome.epoch, m_epoch );
01628     MemWrite( &welcome.exectime, m_exectime );
01629     MemWrite( &welcome.pid, pid );
01630     MemWrite( &welcome.samplingPeriod, m_samplingPeriod );
01631     MemWrite( &welcome.flags, flags );
01632     MemWrite( &welcome.cpuArch, cpuArch );
01633     memcpy( welcome.cpuManufacturer, manufacturer, 12 );
01634     MemWrite( &welcome.cpuId, cpuId );
01635     memcpy( welcome.programName, procname, pnsz );
01636     memset( welcome.programName + pnsz, 0, WelcomeMessageProgramNameSize - pnsz );
01637     memcpy( welcome.hostInfo, hostinfo, hisz );
01638     memset( welcome.hostInfo + hisz, 0, WelcomeMessageHostInfoSize - hisz );
01639 
01640     moodycamel::ConsumerToken token( GetQueue() );
01641 
01642     ListenSocket listen;
01643     bool isListening = false;
01644     if( !dataPortSearch )
01645     {
01646         isListening = listen.Listen( dataPort, 4 );
01647     }
01648     else
01649     {
01650         for( uint32_t i=0; i<20; i++ )
01651         {
01652             if( listen.Listen( dataPort+i, 4 ) )
01653             {
01654                 dataPort += i;
01655                 isListening = true;
01656                 break;
01657             }
01658         }
01659     }
01660     if( !isListening )
01661     {
01662         for(;;)
01663         {
01664             if( ShouldExit() )
01665             {
01666                 m_shutdownFinished.store( true, std::memory_order_relaxed );
01667                 return;
01668             }
01669 
01670             ClearQueues( token );
01671             std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) );
01672         }
01673     }
01674 
01675 #ifndef TRACY_NO_BROADCAST
01676     m_broadcast = (UdpBroadcast*)tracy_malloc( sizeof( UdpBroadcast ) );
01677     new(m_broadcast) UdpBroadcast();
01678 #  ifdef TRACY_ONLY_LOCALHOST
01679     const char* addr = "127.255.255.255";
01680 #  else
01681     const char* addr = "255.255.255.255";
01682 #  endif
01683     if( !m_broadcast->Open( addr, broadcastPort ) )
01684     {
01685         m_broadcast->~UdpBroadcast();
01686         tracy_free( m_broadcast );
01687         m_broadcast = nullptr;
01688     }
01689 #endif
01690 
01691     int broadcastLen = 0;
01692     auto& broadcastMsg = GetBroadcastMessage( procname, pnsz, broadcastLen, dataPort );
01693     uint64_t lastBroadcast = 0;
01694 
01695     // Connections loop.
01696     // Each iteration of the loop handles whole connection. Multiple iterations will only
01697     // happen in the on-demand mode or when handshake fails.
01698     for(;;)
01699     {
01700         // Wait for incoming connection
01701         for(;;)
01702         {
01703 #ifndef TRACY_NO_EXIT
01704             if( !m_noExit && ShouldExit() )
01705             {
01706                 if( m_broadcast )
01707                 {
01708                     broadcastMsg.activeTime = -1;
01709                     m_broadcast->Send( broadcastPort, &broadcastMsg, broadcastLen );
01710                 }
01711                 m_shutdownFinished.store( true, std::memory_order_relaxed );
01712                 return;
01713             }
01714 #endif
01715             m_sock = listen.Accept();
01716             if( m_sock ) break;
01717 #ifndef TRACY_ON_DEMAND
01718             ProcessSysTime();
01719 #  ifdef TRACY_HAS_SYSPOWER
01720             m_sysPower.Tick();
01721 #  endif
01722 #endif
01723 
01724             if( m_broadcast )
01725             {
01726                 const auto t = std::chrono::high_resolution_clock::now().time_since_epoch().count();
01727                 if( t - lastBroadcast > 3000000000 )  // 3s
01728                 {
01729                     m_programNameLock.lock();
01730                     if( m_programName )
01731                     {
01732                         broadcastMsg = GetBroadcastMessage( m_programName, strlen( m_programName ), broadcastLen, dataPort );
01733                         m_programName = nullptr;
01734                     }
01735                     m_programNameLock.unlock();
01736 
01737                     lastBroadcast = t;
01738                     const auto ts = std::chrono::duration_cast<std::chrono::seconds>( std::chrono::system_clock::now().time_since_epoch() ).count();
01739                     broadcastMsg.activeTime = int32_t( ts - m_epoch );
01740                     assert( broadcastMsg.activeTime >= 0 );
01741                     m_broadcast->Send( broadcastPort, &broadcastMsg, broadcastLen );
01742                 }
01743             }
01744         }
01745 
01746         if( m_broadcast )
01747         {
01748             lastBroadcast = 0;
01749             broadcastMsg.activeTime = -1;
01750             m_broadcast->Send( broadcastPort, &broadcastMsg, broadcastLen );
01751         }
01752 
01753         // Handshake
01754         {
01755             char shibboleth[HandshakeShibbolethSize];
01756             auto res = m_sock->ReadRaw( shibboleth, HandshakeShibbolethSize, 2000 );
01757             if( !res || memcmp( shibboleth, HandshakeShibboleth, HandshakeShibbolethSize ) != 0 )
01758             {
01759                 m_sock->~Socket();
01760                 tracy_free( m_sock );
01761                 m_sock = nullptr;
01762                 continue;
01763             }
01764 
01765             uint32_t protocolVersion;
01766             res = m_sock->ReadRaw( &protocolVersion, sizeof( protocolVersion ), 2000 );
01767             if( !res )
01768             {
01769                 m_sock->~Socket();
01770                 tracy_free( m_sock );
01771                 m_sock = nullptr;
01772                 continue;
01773             }
01774 
01775             if( protocolVersion != ProtocolVersion )
01776             {
01777                 HandshakeStatus status = HandshakeProtocolMismatch;
01778                 m_sock->Send( &status, sizeof( status ) );
01779                 m_sock->~Socket();
01780                 tracy_free( m_sock );
01781                 m_sock = nullptr;
01782                 continue;
01783             }
01784         }
01785 
01786 #ifdef TRACY_ON_DEMAND
01787         const auto currentTime = GetTime();
01788         ClearQueues( token );
01789         m_connectionId.fetch_add( 1, std::memory_order_release );
01790 #endif
01791         m_isConnected.store( true, std::memory_order_release );
01792 
01793         HandshakeStatus handshake = HandshakeWelcome;
01794         m_sock->Send( &handshake, sizeof( handshake ) );
01795 
01796         LZ4_resetStream( (LZ4_stream_t*)m_stream );
01797         m_sock->Send( &welcome, sizeof( welcome ) );
01798 
01799         m_threadCtx = 0;
01800         m_refTimeSerial = 0;
01801         m_refTimeCtx = 0;
01802         m_refTimeGpu = 0;
01803 
01804 #ifdef TRACY_ON_DEMAND
01805         OnDemandPayloadMessage onDemand;
01806         onDemand.frames = m_frameCount.load( std::memory_order_relaxed );
01807         onDemand.currentTime = currentTime;
01808 
01809         m_sock->Send( &onDemand, sizeof( onDemand ) );
01810 
01811         m_deferredLock.lock();
01812         for( auto& item : m_deferredQueue )
01813         {
01814             uint64_t ptr;
01815             uint16_t size;
01816             const auto idx = MemRead<uint8_t>( &item.hdr.idx );
01817             switch( (QueueType)idx )
01818             {
01819             case QueueType::MessageAppInfo:
01820                 ptr = MemRead<uint64_t>( &item.messageFat.text );
01821                 size = MemRead<uint16_t>( &item.messageFat.size );
01822                 SendSingleString( (const char*)ptr, size );
01823                 break;
01824             case QueueType::LockName:
01825                 ptr = MemRead<uint64_t>( &item.lockNameFat.name );
01826                 size = MemRead<uint16_t>( &item.lockNameFat.size );
01827                 SendSingleString( (const char*)ptr, size );
01828                 break;
01829             case QueueType::GpuContextName:
01830                 ptr = MemRead<uint64_t>( &item.gpuContextNameFat.ptr );
01831                 size = MemRead<uint16_t>( &item.gpuContextNameFat.size );
01832                 SendSingleString( (const char*)ptr, size );
01833                 break;
01834             default:
01835                 break;
01836             }
01837             AppendData( &item, QueueDataSize[idx] );
01838         }
01839         m_deferredLock.unlock();
01840 #endif
01841 
01842         // Main communications loop
01843         int keepAlive = 0;
01844         for(;;)
01845         {
01846             ProcessSysTime();
01847 #ifdef TRACY_HAS_SYSPOWER
01848             m_sysPower.Tick();
01849 #endif
01850             const auto status = Dequeue( token );
01851             const auto serialStatus = DequeueSerial();
01852             if( status == DequeueStatus::ConnectionLost || serialStatus == DequeueStatus::ConnectionLost )
01853             {
01854                 break;
01855             }
01856             else if( status == DequeueStatus::QueueEmpty && serialStatus == DequeueStatus::QueueEmpty )
01857             {
01858                 if( ShouldExit() ) break;
01859                 if( m_bufferOffset != m_bufferStart )
01860                 {
01861                     if( !CommitData() ) break;
01862                 }
01863                 if( keepAlive == 500 )
01864                 {
01865                     QueueItem ka;
01866                     ka.hdr.type = QueueType::KeepAlive;
01867                     AppendData( &ka, QueueDataSize[ka.hdr.idx] );
01868                     if( !CommitData() ) break;
01869 
01870                     keepAlive = 0;
01871                 }
01872                 else if( !m_sock->HasData() )
01873                 {
01874                     keepAlive++;
01875                     std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) );
01876                 }
01877             }
01878             else
01879             {
01880                 keepAlive = 0;
01881             }
01882 
01883             bool connActive = true;
01884             while( m_sock->HasData() )
01885             {
01886                 connActive = HandleServerQuery();
01887                 if( !connActive ) break;
01888             }
01889             if( !connActive ) break;
01890         }
01891         if( ShouldExit() ) break;
01892 
01893         m_isConnected.store( false, std::memory_order_release );
01894 #ifdef TRACY_ON_DEMAND
01895         m_bufferOffset = 0;
01896         m_bufferStart = 0;
01897 #endif
01898 
01899         m_sock->~Socket();
01900         tracy_free( m_sock );
01901         m_sock = nullptr;
01902 
01903 #ifndef TRACY_ON_DEMAND
01904         // Client is no longer available here. Accept incoming connections, but reject handshake.
01905         for(;;)
01906         {
01907             if( ShouldExit() )
01908             {
01909                 m_shutdownFinished.store( true, std::memory_order_relaxed );
01910                 return;
01911             }
01912 
01913             ClearQueues( token );
01914 
01915             m_sock = listen.Accept();
01916             if( m_sock )
01917             {
01918                 char shibboleth[HandshakeShibbolethSize];
01919                 auto res = m_sock->ReadRaw( shibboleth, HandshakeShibbolethSize, 1000 );
01920                 if( !res || memcmp( shibboleth, HandshakeShibboleth, HandshakeShibbolethSize ) != 0 )
01921                 {
01922                     m_sock->~Socket();
01923                     tracy_free( m_sock );
01924                     m_sock = nullptr;
01925                     continue;
01926                 }
01927 
01928                 uint32_t protocolVersion;
01929                 res = m_sock->ReadRaw( &protocolVersion, sizeof( protocolVersion ), 1000 );
01930                 if( !res )
01931                 {
01932                     m_sock->~Socket();
01933                     tracy_free( m_sock );
01934                     m_sock = nullptr;
01935                     continue;
01936                 }
01937 
01938                 HandshakeStatus status = HandshakeNotAvailable;
01939                 m_sock->Send( &status, sizeof( status ) );
01940                 m_sock->~Socket();
01941                 tracy_free( m_sock );
01942             }
01943         }
01944 #endif
01945     }
01946     // End of connections loop
01947 
01948     // Wait for symbols thread to terminate. Symbol resolution will continue in this thread.
01949 #ifdef TRACY_HAS_CALLSTACK
01950     while( s_symbolThreadGone.load() == false ) { YieldThread(); }
01951 #endif
01952 
01953     // Client is exiting. Send items remaining in queues.
01954     for(;;)
01955     {
01956         const auto status = Dequeue( token );
01957         const auto serialStatus = DequeueSerial();
01958         if( status == DequeueStatus::ConnectionLost || serialStatus == DequeueStatus::ConnectionLost )
01959         {
01960             m_shutdownFinished.store( true, std::memory_order_relaxed );
01961             return;
01962         }
01963         else if( status == DequeueStatus::QueueEmpty && serialStatus == DequeueStatus::QueueEmpty )
01964         {
01965             if( m_bufferOffset != m_bufferStart ) CommitData();
01966             break;
01967         }
01968 
01969         while( m_sock->HasData() )
01970         {
01971             if( !HandleServerQuery() )
01972             {
01973                 m_shutdownFinished.store( true, std::memory_order_relaxed );
01974                 return;
01975             }
01976         }
01977 
01978 #ifdef TRACY_HAS_CALLSTACK
01979         for(;;)
01980         {
01981             auto si = m_symbolQueue.front();
01982             if( !si ) break;
01983             HandleSymbolQueueItem( *si );
01984             m_symbolQueue.pop();
01985         }
01986 #endif
01987     }
01988 
01989     // Send client termination notice to the server
01990     QueueItem terminate;
01991     MemWrite( &terminate.hdr.type, QueueType::Terminate );
01992     if( !SendData( (const char*)&terminate, 1 ) )
01993     {
01994         m_shutdownFinished.store( true, std::memory_order_relaxed );
01995         return;
01996     }
01997     // Handle remaining server queries
01998     for(;;)
01999     {
02000         while( m_sock->HasData() )
02001         {
02002             if( !HandleServerQuery() )
02003             {
02004                 m_shutdownFinished.store( true, std::memory_order_relaxed );
02005                 return;
02006             }
02007         }
02008 #ifdef TRACY_HAS_CALLSTACK
02009         for(;;)
02010         {
02011             auto si = m_symbolQueue.front();
02012             if( !si ) break;
02013             HandleSymbolQueueItem( *si );
02014             m_symbolQueue.pop();
02015         }
02016 #endif
02017         const auto status = Dequeue( token );
02018         const auto serialStatus = DequeueSerial();
02019         if( status == DequeueStatus::ConnectionLost || serialStatus == DequeueStatus::ConnectionLost )
02020         {
02021             m_shutdownFinished.store( true, std::memory_order_relaxed );
02022             return;
02023         }
02024         if( m_bufferOffset != m_bufferStart )
02025         {
02026             if( !CommitData() )
02027             {
02028                 m_shutdownFinished.store( true, std::memory_order_relaxed );
02029                 return;
02030             }
02031         }
02032     }
02033 }
