02035 #ifndef TRACY_NO_FRAME_IMAGE
02036 void Profiler::CompressWorker()
02037 {
02038     ThreadExitHandler threadExitHandler;
02039     SetThreadName( "Tracy DXT1" );
02040     while( m_timeBegin.load( std::memory_order_relaxed ) == 0 ) std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) );
02041 
02042 #ifdef TRACY_USE_RPMALLOC
02043     rpmalloc_thread_initialize();
02044 #endif
02045 
02046     for(;;)
02047     {
02048         const auto shouldExit = ShouldExit();
02049 
02050         {
02051             bool lockHeld = true;
02052             while( !m_fiLock.try_lock() )
02053             {
02054                 if( m_shutdownManual.load( std::memory_order_relaxed ) )
02055                 {
02056                     lockHeld = false;
02057                     break;
02058                 }
02059             }
02060             if( !m_fiQueue.empty() ) m_fiQueue.swap( m_fiDequeue );
02061             if( lockHeld )
02062             {
02063                 m_fiLock.unlock();
02064             }
02065         }
02066 
02067         const auto sz = m_fiDequeue.size();
02068         if( sz > 0 )
02069         {
02070             auto fi = m_fiDequeue.data();
02071             auto end = fi + sz;
02072             while( fi != end )
02073             {
02074                 const auto w = fi->w;
02075                 const auto h = fi->h;
02076                 const auto csz = size_t( w * h / 2 );
02077                 auto etc1buf = (char*)tracy_malloc( csz );
02078                 CompressImageDxt1( (const char*)fi->image, etc1buf, w, h );
02079                 tracy_free( fi->image );
02080 
02081                 TracyLfqPrepare( QueueType::FrameImage );
02082                 MemWrite( &item->frameImageFat.image, (uint64_t)etc1buf );
02083                 MemWrite( &item->frameImageFat.frame, fi->frame );
02084                 MemWrite( &item->frameImageFat.w, w );
02085                 MemWrite( &item->frameImageFat.h, h );
02086                 uint8_t flip = fi->flip;
02087                 MemWrite( &item->frameImageFat.flip, flip );
02088                 TracyLfqCommit;
02089 
02090                 fi++;
02091             }
02092             m_fiDequeue.clear();
02093         }
02094         else
02095         {
02096             std::this_thread::sleep_for( std::chrono::milliseconds( 20 ) );
02097         }
02098 
02099         if( shouldExit )
02100         {
02101             return;
02102         }
02103     }
02104 }
02105 #endif
