02107 static void FreeAssociatedMemory( const QueueItem& item )
02108 {
02109     if( item.hdr.idx >= (int)QueueType::Terminate ) return;
02110 
02111     uint64_t ptr;
02112     switch( item.hdr.type )
02113     {
02114     case QueueType::ZoneText:
02115     case QueueType::ZoneName:
02116         ptr = MemRead<uint64_t>( &item.zoneTextFat.text );
02117         tracy_free( (void*)ptr );
02118         break;
02119     case QueueType::MessageColor:
02120     case QueueType::MessageColorCallstack:
02121         ptr = MemRead<uint64_t>( &item.messageColorFat.text );
02122         tracy_free( (void*)ptr );
02123         break;
02124     case QueueType::Message:
02125     case QueueType::MessageCallstack:
02126 #ifndef TRACY_ON_DEMAND
02127     case QueueType::MessageAppInfo:
02128 #endif
02129         ptr = MemRead<uint64_t>( &item.messageFat.text );
02130         tracy_free( (void*)ptr );
02131         break;
02132     case QueueType::ZoneBeginAllocSrcLoc:
02133     case QueueType::ZoneBeginAllocSrcLocCallstack:
02134         ptr = MemRead<uint64_t>( &item.zoneBegin.srcloc );
02135         tracy_free( (void*)ptr );
02136         break;
02137     case QueueType::GpuZoneBeginAllocSrcLoc:
02138     case QueueType::GpuZoneBeginAllocSrcLocCallstack:
02139     case QueueType::GpuZoneBeginAllocSrcLocSerial:
02140     case QueueType::GpuZoneBeginAllocSrcLocCallstackSerial:
02141         ptr = MemRead<uint64_t>( &item.gpuZoneBegin.srcloc );
02142         tracy_free( (void*)ptr );
02143         break;
02144     case QueueType::CallstackSerial:
02145     case QueueType::Callstack:
02146         ptr = MemRead<uint64_t>( &item.callstackFat.ptr );
02147         tracy_free( (void*)ptr );
02148         break;
02149     case QueueType::CallstackAlloc:
02150         ptr = MemRead<uint64_t>( &item.callstackAllocFat.nativePtr );
02151         tracy_free( (void*)ptr );
02152         ptr = MemRead<uint64_t>( &item.callstackAllocFat.ptr );
02153         tracy_free( (void*)ptr );
02154         break;
02155     case QueueType::CallstackSample:
02156     case QueueType::CallstackSampleContextSwitch:
02157         ptr = MemRead<uint64_t>( &item.callstackSampleFat.ptr );
02158         tracy_free( (void*)ptr );
02159         break;
02160     case QueueType::FrameImage:
02161         ptr = MemRead<uint64_t>( &item.frameImageFat.image );
02162         tracy_free( (void*)ptr );
02163         break;
02164 #ifdef TRACY_HAS_CALLSTACK
02165     case QueueType::CallstackFrameSize:
02166     {
02167         InitRpmalloc();
02168         auto size = MemRead<uint8_t>( &item.callstackFrameSizeFat.size );
02169         auto data = (const CallstackEntry*)MemRead<uint64_t>( &item.callstackFrameSizeFat.data );
02170         for( uint8_t i=0; i<size; i++ )
02171         {
02172             const auto& frame = data[i];
02173             tracy_free_fast( (void*)frame.name );
02174             tracy_free_fast( (void*)frame.file );
02175         }
02176         tracy_free_fast( (void*)data );
02177         break;
02178     }
02179     case QueueType::SymbolInformation:
02180     {
02181         uint8_t needFree = MemRead<uint8_t>( &item.symbolInformationFat.needFree );
02182         if( needFree )
02183         {
02184             ptr = MemRead<uint64_t>( &item.symbolInformationFat.fileString );
02185             tracy_free( (void*)ptr );
02186         }
02187         break;
02188     }
02189     case QueueType::SymbolCodeMetadata:
02190         ptr = MemRead<uint64_t>( &item.symbolCodeMetadata.ptr );
02191         tracy_free( (void*)ptr );
02192         break;
02193 #endif
02194 #ifndef TRACY_ON_DEMAND
02195     case QueueType::LockName:
02196         ptr = MemRead<uint64_t>( &item.lockNameFat.name );
02197         tracy_free( (void*)ptr );
02198         break;
02199     case QueueType::GpuContextName:
02200         ptr = MemRead<uint64_t>( &item.gpuContextNameFat.ptr );
02201         tracy_free( (void*)ptr );
02202         break;
02203 #endif
02204 #ifdef TRACY_ON_DEMAND
02205     case QueueType::MessageAppInfo:
02206     case QueueType::GpuContextName:
02207         // Don't free memory associated with deferred messages.
02208         break;
02209 #endif
02210 #ifdef TRACY_HAS_SYSTEM_TRACING
02211     case QueueType::ExternalNameMetadata:
02212         ptr = MemRead<uint64_t>( &item.externalNameMetadata.name );
02213         tracy_free( (void*)ptr );
02214         ptr = MemRead<uint64_t>( &item.externalNameMetadata.threadName );
02215         tracy_free_fast( (void*)ptr );
02216         break;
02217 #endif
02218     case QueueType::SourceCodeMetadata:
02219         ptr = MemRead<uint64_t>( &item.sourceCodeMetadata.ptr );
02220         tracy_free( (void*)ptr );
02221         break;
02222     default:
02223         break;
02224     }
02225 }
