02227 void Profiler::ClearQueues( moodycamel::ConsumerToken& token )
02228 {
02229     for(;;)
02230     {
02231         const auto sz = GetQueue().try_dequeue_bulk_single( token, [](const uint64_t&){}, []( QueueItem* item, size_t sz ) { assert( sz > 0 ); while( sz-- > 0 ) FreeAssociatedMemory( *item++ ); } );
02232         if( sz == 0 ) break;
02233     }
02234 
02235     ClearSerial();
02236 }
02237 
02238 void Profiler::ClearSerial()
02239 {
02240     bool lockHeld = true;
02241     while( !m_serialLock.try_lock() )
02242     {
02243         if( m_shutdownManual.load( std::memory_order_relaxed ) )
02244         {
02245             lockHeld = false;
02246             break;
02247         }
02248     }
02249     for( auto& v : m_serialQueue ) FreeAssociatedMemory( v );
02250     m_serialQueue.clear();
02251     if( lockHeld )
02252     {
02253         m_serialLock.unlock();
02254     }
02255 
02256     for( auto& v : m_serialDequeue ) FreeAssociatedMemory( v );
02257     m_serialDequeue.clear();
02258 }
