02260 Profiler::DequeueStatus Profiler::Dequeue( moodycamel::ConsumerToken& token )
02261 {
02262     bool connectionLost = false;
02263     const auto sz = GetQueue().try_dequeue_bulk_single( token,
02264         [this, &connectionLost] ( const uint32_t& threadId )
02265         {
02266             if( ThreadCtxCheck( threadId ) == ThreadCtxStatus::ConnectionLost ) connectionLost = true;
02267         },
02268         [this, &connectionLost] ( QueueItem* item, size_t sz )
02269         {
02270             if( connectionLost ) return;
02271             InitRpmalloc();
02272             assert( sz > 0 );
02273             int64_t refThread = m_refTimeThread;
02274             int64_t refCtx = m_refTimeCtx;
02275             int64_t refGpu = m_refTimeGpu;
02276             while( sz-- > 0 )
02277             {
02278                 uint64_t ptr;
02279                 uint16_t size;
02280                 auto idx = MemRead<uint8_t>( &item->hdr.idx );
02281                 if( idx < (int)QueueType::Terminate )
02282                 {
02283                     switch( (QueueType)idx )
02284                     {
02285                     case QueueType::ZoneText:
02286                     case QueueType::ZoneName:
02287                         ptr = MemRead<uint64_t>( &item->zoneTextFat.text );
02288                         size = MemRead<uint16_t>( &item->zoneTextFat.size );
02289                         SendSingleString( (const char*)ptr, size );
02290                         tracy_free_fast( (void*)ptr );
02291                         break;
02292                     case QueueType::Message:
02293                     case QueueType::MessageCallstack:
02294                         ptr = MemRead<uint64_t>( &item->messageFat.text );
02295                         size = MemRead<uint16_t>( &item->messageFat.size );
02296                         SendSingleString( (const char*)ptr, size );
02297                         tracy_free_fast( (void*)ptr );
02298                         break;
02299                     case QueueType::MessageColor:
02300                     case QueueType::MessageColorCallstack:
02301                         ptr = MemRead<uint64_t>( &item->messageColorFat.text );
02302                         size = MemRead<uint16_t>( &item->messageColorFat.size );
02303                         SendSingleString( (const char*)ptr, size );
02304                         tracy_free_fast( (void*)ptr );
02305                         break;
02306                     case QueueType::MessageAppInfo:
02307                         ptr = MemRead<uint64_t>( &item->messageFat.text );
02308                         size = MemRead<uint16_t>( &item->messageFat.size );
02309                         SendSingleString( (const char*)ptr, size );
02310 #ifndef TRACY_ON_DEMAND
02311                         tracy_free_fast( (void*)ptr );
02312 #endif
02313                         break;
02314                     case QueueType::ZoneBeginAllocSrcLoc:
02315                     case QueueType::ZoneBeginAllocSrcLocCallstack:
02316                     {
02317                         int64_t t = MemRead<int64_t>( &item->zoneBegin.time );
02318                         int64_t dt = t - refThread;
02319                         refThread = t;
02320                         MemWrite( &item->zoneBegin.time, dt );
02321                         ptr = MemRead<uint64_t>( &item->zoneBegin.srcloc );
02322                         SendSourceLocationPayload( ptr );
02323                         tracy_free_fast( (void*)ptr );
02324                         break;
02325                     }
02326                     case QueueType::Callstack:
02327                         ptr = MemRead<uint64_t>( &item->callstackFat.ptr );
02328                         SendCallstackPayload( ptr );
02329                         tracy_free_fast( (void*)ptr );
02330                         break;
02331                     case QueueType::CallstackAlloc:
02332                         ptr = MemRead<uint64_t>( &item->callstackAllocFat.nativePtr );
02333                         if( ptr != 0 )
02334                         {
02335                             CutCallstack( (void*)ptr, "lua_pcall" );
02336                             SendCallstackPayload( ptr );
02337                             tracy_free_fast( (void*)ptr );
02338                         }
02339                         ptr = MemRead<uint64_t>( &item->callstackAllocFat.ptr );
02340                         SendCallstackAlloc( ptr );
02341                         tracy_free_fast( (void*)ptr );
02342                         break;
02343                     case QueueType::CallstackSample:
02344                     case QueueType::CallstackSampleContextSwitch:
02345                     {
02346                         ptr = MemRead<uint64_t>( &item->callstackSampleFat.ptr );
02347                         SendCallstackPayload64( ptr );
02348                         tracy_free_fast( (void*)ptr );
02349                         int64_t t = MemRead<int64_t>( &item->callstackSampleFat.time );
02350                         int64_t dt = t - refCtx;
02351                         refCtx = t;
02352                         MemWrite( &item->callstackSampleFat.time, dt );
02353                         break;
02354                     }
02355                     case QueueType::FrameImage:
02356                     {
02357                         ptr = MemRead<uint64_t>( &item->frameImageFat.image );
02358                         const auto w = MemRead<uint16_t>( &item->frameImageFat.w );
02359                         const auto h = MemRead<uint16_t>( &item->frameImageFat.h );
02360                         const auto csz = size_t( w * h / 2 );
02361                         SendLongString( ptr, (const char*)ptr, csz, QueueType::FrameImageData );
02362                         tracy_free_fast( (void*)ptr );
02363                         break;
02364                     }
02365                     case QueueType::ZoneBegin:
02366                     case QueueType::ZoneBeginCallstack:
02367                     {
02368                         int64_t t = MemRead<int64_t>( &item->zoneBegin.time );
02369                         int64_t dt = t - refThread;
02370                         refThread = t;
02371                         MemWrite( &item->zoneBegin.time, dt );
02372                         break;
02373                     }
02374                     case QueueType::ZoneEnd:
02375                     {
02376                         int64_t t = MemRead<int64_t>( &item->zoneEnd.time );
02377                         int64_t dt = t - refThread;
02378                         refThread = t;
02379                         MemWrite( &item->zoneEnd.time, dt );
02380                         break;
02381                     }
02382                     case QueueType::GpuZoneBegin:
02383                     case QueueType::GpuZoneBeginCallstack:
02384                     {
02385                         int64_t t = MemRead<int64_t>( &item->gpuZoneBegin.cpuTime );
02386                         int64_t dt = t - refThread;
02387                         refThread = t;
02388                         MemWrite( &item->gpuZoneBegin.cpuTime, dt );
02389                         break;
02390                     }
02391                     case QueueType::GpuZoneBeginAllocSrcLoc:
02392                     case QueueType::GpuZoneBeginAllocSrcLocCallstack:
02393                     {
02394                         int64_t t = MemRead<int64_t>( &item->gpuZoneBegin.cpuTime );
02395                         int64_t dt = t - refThread;
02396                         refThread = t;
02397                         MemWrite( &item->gpuZoneBegin.cpuTime, dt );
02398                         ptr = MemRead<uint64_t>( &item->gpuZoneBegin.srcloc );
02399                         SendSourceLocationPayload( ptr );
02400                         tracy_free_fast( (void*)ptr );
02401                         break;
02402                     }
02403                     case QueueType::GpuZoneEnd:
02404                     {
02405                         int64_t t = MemRead<int64_t>( &item->gpuZoneEnd.cpuTime );
02406                         int64_t dt = t - refThread;
02407                         refThread = t;
02408                         MemWrite( &item->gpuZoneEnd.cpuTime, dt );
02409                         break;
02410                     }
02411                     case QueueType::GpuContextName:
02412                         ptr = MemRead<uint64_t>( &item->gpuContextNameFat.ptr );
02413                         size = MemRead<uint16_t>( &item->gpuContextNameFat.size );
02414                         SendSingleString( (const char*)ptr, size );
02415 #ifndef TRACY_ON_DEMAND
02416                         tracy_free_fast( (void*)ptr );
02417 #endif
02418                         break;
02419                     case QueueType::PlotDataInt:
02420                     case QueueType::PlotDataFloat:
02421                     case QueueType::PlotDataDouble:
02422                     {
02423                         int64_t t = MemRead<int64_t>( &item->plotDataInt.time );
02424                         int64_t dt = t - refThread;
02425                         refThread = t;
02426                         MemWrite( &item->plotDataInt.time, dt );
02427                         break;
02428                     }
02429                     case QueueType::ContextSwitch:
02430                     {
02431                         int64_t t = MemRead<int64_t>( &item->contextSwitch.time );
02432                         int64_t dt = t - refCtx;
02433                         refCtx = t;
02434                         MemWrite( &item->contextSwitch.time, dt );
02435                         break;
02436                     }
02437                     case QueueType::ThreadWakeup:
02438                     {
02439                         int64_t t = MemRead<int64_t>( &item->threadWakeup.time );
02440                         int64_t dt = t - refCtx;
02441                         refCtx = t;
02442                         MemWrite( &item->threadWakeup.time, dt );
02443                         break;
02444                     }
02445                     case QueueType::GpuTime:
02446                     {
02447                         int64_t t = MemRead<int64_t>( &item->gpuTime.gpuTime );
02448                         int64_t dt = t - refGpu;
02449                         refGpu = t;
02450                         MemWrite( &item->gpuTime.gpuTime, dt );
02451                         break;
02452                     }
02453 #ifdef TRACY_HAS_CALLSTACK
02454                     case QueueType::CallstackFrameSize:
02455                     {
02456                         auto data = (const CallstackEntry*)MemRead<uint64_t>( &item->callstackFrameSizeFat.data );
02457                         auto datasz = MemRead<uint8_t>( &item->callstackFrameSizeFat.size );
02458                         auto imageName = (const char*)MemRead<uint64_t>( &item->callstackFrameSizeFat.imageName );
02459                         SendSingleString( imageName );
02460                         AppendData( item++, QueueDataSize[idx] );
02461 
02462                         for( uint8_t i=0; i<datasz; i++ )
02463                         {
02464                             const auto& frame = data[i];
02465 
02466                             SendSingleString( frame.name );
02467                             SendSecondString( frame.file );
02468 
02469                             QueueItem item;
02470                             MemWrite( &item.hdr.type, QueueType::CallstackFrame );
02471                             MemWrite( &item.callstackFrame.line, frame.line );
02472                             MemWrite( &item.callstackFrame.symAddr, frame.symAddr );
02473                             MemWrite( &item.callstackFrame.symLen, frame.symLen );
02474 
02475                             AppendData( &item, QueueDataSize[(int)QueueType::CallstackFrame] );
02476 
02477                             tracy_free_fast( (void*)frame.name );
02478                             tracy_free_fast( (void*)frame.file );
02479                         }
02480                         tracy_free_fast( (void*)data );
02481                         continue;
02482                     }
02483                     case QueueType::SymbolInformation:
02484                     {
02485                         auto fileString = (const char*)MemRead<uint64_t>( &item->symbolInformationFat.fileString );
02486                         auto needFree = MemRead<uint8_t>( &item->symbolInformationFat.needFree );
02487                         SendSingleString( fileString );
02488                         if( needFree ) tracy_free_fast( (void*)fileString );
02489                         break;
02490                     }
02491                     case QueueType::SymbolCodeMetadata:
02492                     {
02493                         auto symbol = MemRead<uint64_t>( &item->symbolCodeMetadata.symbol );
02494                         auto ptr = (const char*)MemRead<uint64_t>( &item->symbolCodeMetadata.ptr );
02495                         auto size = MemRead<uint32_t>( &item->symbolCodeMetadata.size );
02496                         SendLongString( symbol, ptr, size, QueueType::SymbolCode );
02497                         tracy_free_fast( (void*)ptr );
02498                         ++item;
02499                         continue;
02500                     }
02501 #endif
02502 #ifdef TRACY_HAS_SYSTEM_TRACING
02503                     case QueueType::ExternalNameMetadata:
02504                     {
02505                         auto thread = MemRead<uint64_t>( &item->externalNameMetadata.thread );
02506                         auto name = (const char*)MemRead<uint64_t>( &item->externalNameMetadata.name );
02507                         auto threadName = (const char*)MemRead<uint64_t>( &item->externalNameMetadata.threadName );
02508                         SendString( thread, threadName, QueueType::ExternalThreadName );
02509                         SendString( thread, name, QueueType::ExternalName );
02510                         tracy_free_fast( (void*)threadName );
02511                         tracy_free_fast( (void*)name );
02512                         ++item;
02513                         continue;
02514                     }
02515 #endif
02516                     case QueueType::SourceCodeMetadata:
02517                     {
02518                         auto ptr = (const char*)MemRead<uint64_t>( &item->sourceCodeMetadata.ptr );
02519                         auto size = MemRead<uint32_t>( &item->sourceCodeMetadata.size );
02520                         auto id = MemRead<uint32_t>( &item->sourceCodeMetadata.id );
02521                         SendLongString( (uint64_t)id, ptr, size, QueueType::SourceCode );
02522                         tracy_free_fast( (void*)ptr );
02523                         ++item;
02524                         continue;
02525                     }
02526                     default:
02527                         assert( false );
02528                         break;
02529                     }
02530                 }
02531                 if( !AppendData( item++, QueueDataSize[idx] ) )
02532                 {
02533                     connectionLost = true;
02534                     m_refTimeThread = refThread;
02535                     m_refTimeCtx = refCtx;
02536                     m_refTimeGpu = refGpu;
02537                     return;
02538                 }
02539             }
02540             m_refTimeThread = refThread;
02541             m_refTimeCtx = refCtx;
02542             m_refTimeGpu = refGpu;
02543         }
02544     );
02545     if( connectionLost ) return DequeueStatus::ConnectionLost;
02546     return sz > 0 ? DequeueStatus::DataDequeued : DequeueStatus::QueueEmpty;
02547 }
02548 
02549 Profiler::DequeueStatus Profiler::DequeueContextSwitches( tracy::moodycamel::ConsumerToken& token, int64_t& timeStop )
02550 {
02551     const auto sz = GetQueue().try_dequeue_bulk_single( token, [] ( const uint64_t& ) {},
02552         [this, &timeStop] ( QueueItem* item, size_t sz )
02553         {
02554             assert( sz > 0 );
02555             int64_t refCtx = m_refTimeCtx;
02556             while( sz-- > 0 )
02557             {
02558                 FreeAssociatedMemory( *item );
02559                 if( timeStop < 0 ) return;
02560                 const auto idx = MemRead<uint8_t>( &item->hdr.idx );
02561                 if( idx == (uint8_t)QueueType::ContextSwitch )
02562                 {
02563                     const auto csTime = MemRead<int64_t>( &item->contextSwitch.time );
02564                     if( csTime > timeStop )
02565                     {
02566                         timeStop = -1;
02567                         m_refTimeCtx = refCtx;
02568                         return;
02569                     }
02570                     int64_t dt = csTime - refCtx;
02571                     refCtx = csTime;
02572                     MemWrite( &item->contextSwitch.time, dt );
02573                     if( !AppendData( item, QueueDataSize[(int)QueueType::ContextSwitch] ) )
02574                     {
02575                         timeStop = -2;
02576                         m_refTimeCtx = refCtx;
02577                         return;
02578                     }
02579                 }
02580                 else if( idx == (uint8_t)QueueType::ThreadWakeup )
02581                 {
02582                     const auto csTime = MemRead<int64_t>( &item->threadWakeup.time );
02583                     if( csTime > timeStop )
02584                     {
02585                         timeStop = -1;
02586                         m_refTimeCtx = refCtx;
02587                         return;
02588                     }
02589                     int64_t dt = csTime - refCtx;
02590                     refCtx = csTime;
02591                     MemWrite( &item->threadWakeup.time, dt );
02592                     if( !AppendData( item, QueueDataSize[(int)QueueType::ThreadWakeup] ) )
02593                     {
02594                         timeStop = -2;
02595                         m_refTimeCtx = refCtx;
02596                         return;
02597                     }
02598                 }
02599                 item++;
02600             }
02601             m_refTimeCtx = refCtx;
02602         }
02603     );
02604 
02605     if( timeStop == -2 ) return DequeueStatus::ConnectionLost;
02606     return ( timeStop == -1 || sz > 0 ) ? DequeueStatus::DataDequeued : DequeueStatus::QueueEmpty;
02607 }
02608 
02609 #define ThreadCtxCheckSerial( _name ) \
02610     uint32_t thread = MemRead<uint32_t>( &item->_name.thread ); \
02611     switch( ThreadCtxCheck( thread ) ) \
02612     { \
02613     case ThreadCtxStatus::Same: break; \
02614     case ThreadCtxStatus::Changed: assert( m_refTimeThread == 0 ); refThread = 0; break; \
02615     case ThreadCtxStatus::ConnectionLost: return DequeueStatus::ConnectionLost; \
02616     default: assert( false ); break; \
02617     }
