02619 Profiler::DequeueStatus Profiler::DequeueSerial()
02620 {
02621     {
02622         bool lockHeld = true;
02623         while( !m_serialLock.try_lock() )
02624         {
02625             if( m_shutdownManual.load( std::memory_order_relaxed ) )
02626             {
02627                 lockHeld = false;
02628                 break;
02629             }
02630         }
02631         if( !m_serialQueue.empty() ) m_serialQueue.swap( m_serialDequeue );
02632         if( lockHeld )
02633         {
02634             m_serialLock.unlock();
02635         }
02636     }
02637 
02638     const auto sz = m_serialDequeue.size();
02639     if( sz > 0 )
02640     {
02641         InitRpmalloc();
02642         int64_t refSerial = m_refTimeSerial;
02643         int64_t refGpu = m_refTimeGpu;
02644 #ifdef TRACY_FIBERS
02645         int64_t refThread = m_refTimeThread;
02646 #endif
02647         auto item = m_serialDequeue.data();
02648         auto end = item + sz;
02649         while( item != end )
02650         {
02651             uint64_t ptr;
02652             auto idx = MemRead<uint8_t>( &item->hdr.idx );
02653             if( idx < (int)QueueType::Terminate )
02654             {
02655                 switch( (QueueType)idx )
02656                 {
02657                 case QueueType::CallstackSerial:
02658                     ptr = MemRead<uint64_t>( &item->callstackFat.ptr );
02659                     SendCallstackPayload( ptr );
02660                     tracy_free_fast( (void*)ptr );
02661                     break;
02662                 case QueueType::LockWait:
02663                 case QueueType::LockSharedWait:
02664                 {
02665                     int64_t t = MemRead<int64_t>( &item->lockWait.time );
02666                     int64_t dt = t - refSerial;
02667                     refSerial = t;
02668                     MemWrite( &item->lockWait.time, dt );
02669                     break;
02670                 }
02671                 case QueueType::LockObtain:
02672                 case QueueType::LockSharedObtain:
02673                 {
02674                     int64_t t = MemRead<int64_t>( &item->lockObtain.time );
02675                     int64_t dt = t - refSerial;
02676                     refSerial = t;
02677                     MemWrite( &item->lockObtain.time, dt );
02678                     break;
02679                 }
02680                 case QueueType::LockRelease:
02681                 case QueueType::LockSharedRelease:
02682                 {
02683                     int64_t t = MemRead<int64_t>( &item->lockRelease.time );
02684                     int64_t dt = t - refSerial;
02685                     refSerial = t;
02686                     MemWrite( &item->lockRelease.time, dt );
02687                     break;
02688                 }
02689                 case QueueType::LockName:
02690                 {
02691                     ptr = MemRead<uint64_t>( &item->lockNameFat.name );
02692                     uint16_t size = MemRead<uint16_t>( &item->lockNameFat.size );
02693                     SendSingleString( (const char*)ptr, size );
02694 #ifndef TRACY_ON_DEMAND
02695                     tracy_free_fast( (void*)ptr );
02696 #endif
02697                     break;
02698                 }
02699                 case QueueType::MemAlloc:
02700                 case QueueType::MemAllocNamed:
02701                 case QueueType::MemAllocCallstack:
02702                 case QueueType::MemAllocCallstackNamed:
02703                 {
02704                     int64_t t = MemRead<int64_t>( &item->memAlloc.time );
02705                     int64_t dt = t - refSerial;
02706                     refSerial = t;
02707                     MemWrite( &item->memAlloc.time, dt );
02708                     break;
02709                 }
02710                 case QueueType::MemFree:
02711                 case QueueType::MemFreeNamed:
02712                 case QueueType::MemFreeCallstack:
02713                 case QueueType::MemFreeCallstackNamed:
02714                 {
02715                     int64_t t = MemRead<int64_t>( &item->memFree.time );
02716                     int64_t dt = t - refSerial;
02717                     refSerial = t;
02718                     MemWrite( &item->memFree.time, dt );
02719                     break;
02720                 }
02721                 case QueueType::GpuZoneBeginSerial:
02722                 case QueueType::GpuZoneBeginCallstackSerial:
02723                 {
02724                     int64_t t = MemRead<int64_t>( &item->gpuZoneBegin.cpuTime );
02725                     int64_t dt = t - refSerial;
02726                     refSerial = t;
02727                     MemWrite( &item->gpuZoneBegin.cpuTime, dt );
02728                     break;
02729                 }
02730                 case QueueType::GpuZoneBeginAllocSrcLocSerial:
02731                 case QueueType::GpuZoneBeginAllocSrcLocCallstackSerial:
02732                 {
02733                     int64_t t = MemRead<int64_t>( &item->gpuZoneBegin.cpuTime );
02734                     int64_t dt = t - refSerial;
02735                     refSerial = t;
02736                     MemWrite( &item->gpuZoneBegin.cpuTime, dt );
02737                     ptr = MemRead<uint64_t>( &item->gpuZoneBegin.srcloc );
02738                     SendSourceLocationPayload( ptr );
02739                     tracy_free_fast( (void*)ptr );
02740                     break;
02741                 }
02742                 case QueueType::GpuZoneEndSerial:
02743                 {
02744                     int64_t t = MemRead<int64_t>( &item->gpuZoneEnd.cpuTime );
02745                     int64_t dt = t - refSerial;
02746                     refSerial = t;
02747                     MemWrite( &item->gpuZoneEnd.cpuTime, dt );
02748                     break;
02749                 }
02750                 case QueueType::GpuTime:
02751                 {
02752                     int64_t t = MemRead<int64_t>( &item->gpuTime.gpuTime );
02753                     int64_t dt = t - refGpu;
02754                     refGpu = t;
02755                     MemWrite( &item->gpuTime.gpuTime, dt );
02756                     break;
02757                 }
02758                 case QueueType::GpuContextName:
02759                 {
02760                     ptr = MemRead<uint64_t>( &item->gpuContextNameFat.ptr );
02761                     uint16_t size = MemRead<uint16_t>( &item->gpuContextNameFat.size );
02762                     SendSingleString( (const char*)ptr, size );
02763 #ifndef TRACY_ON_DEMAND
02764                     tracy_free_fast( (void*)ptr );
02765 #endif
02766                     break;
02767                 }
02768 #ifdef TRACY_FIBERS
02769                 case QueueType::ZoneBegin:
02770                 case QueueType::ZoneBeginCallstack:
02771                 {
02772                     ThreadCtxCheckSerial( zoneBeginThread );
02773                     int64_t t = MemRead<int64_t>( &item->zoneBegin.time );
02774                     int64_t dt = t - refThread;
02775                     refThread = t;
02776                     MemWrite( &item->zoneBegin.time, dt );
02777                     break;
02778                 }
02779                 case QueueType::ZoneBeginAllocSrcLoc:
02780                 case QueueType::ZoneBeginAllocSrcLocCallstack:
02781                 {
02782                     ThreadCtxCheckSerial( zoneBeginThread );
02783                     int64_t t = MemRead<int64_t>( &item->zoneBegin.time );
02784                     int64_t dt = t - refThread;
02785                     refThread = t;
02786                     MemWrite( &item->zoneBegin.time, dt );
02787                     ptr = MemRead<uint64_t>( &item->zoneBegin.srcloc );
02788                     SendSourceLocationPayload( ptr );
02789                     tracy_free_fast( (void*)ptr );
02790                     break;
02791                 }
02792                 case QueueType::ZoneEnd:
02793                 {
02794                     ThreadCtxCheckSerial( zoneEndThread );
02795                     int64_t t = MemRead<int64_t>( &item->zoneEnd.time );
02796                     int64_t dt = t - refThread;
02797                     refThread = t;
02798                     MemWrite( &item->zoneEnd.time, dt );
02799                     break;
02800                 }
02801                 case QueueType::ZoneText:
02802                 case QueueType::ZoneName:
02803                 {
02804                     ThreadCtxCheckSerial( zoneTextFatThread );
02805                     ptr = MemRead<uint64_t>( &item->zoneTextFat.text );
02806                     uint16_t size = MemRead<uint16_t>( &item->zoneTextFat.size );
02807                     SendSingleString( (const char*)ptr, size );
02808                     tracy_free_fast( (void*)ptr );
02809                     break;
02810                 }
02811                 case QueueType::Message:
02812                 case QueueType::MessageCallstack:
02813                 {
02814                     ThreadCtxCheckSerial( messageFatThread );
02815                     ptr = MemRead<uint64_t>( &item->messageFat.text );
02816                     uint16_t size = MemRead<uint16_t>( &item->messageFat.size );
02817                     SendSingleString( (const char*)ptr, size );
02818                     tracy_free_fast( (void*)ptr );
02819                     break;
02820                 }
02821                 case QueueType::MessageColor:
02822                 case QueueType::MessageColorCallstack:
02823                 {
02824                     ThreadCtxCheckSerial( messageColorFatThread );
02825                     ptr = MemRead<uint64_t>( &item->messageColorFat.text );
02826                     uint16_t size = MemRead<uint16_t>( &item->messageColorFat.size );
02827                     SendSingleString( (const char*)ptr, size );
02828                     tracy_free_fast( (void*)ptr );
02829                     break;
02830                 }
02831                 case QueueType::Callstack:
02832                 {
02833                     ThreadCtxCheckSerial( callstackFatThread );
02834                     ptr = MemRead<uint64_t>( &item->callstackFat.ptr );
02835                     SendCallstackPayload( ptr );
02836                     tracy_free_fast( (void*)ptr );
02837                     break;
02838                 }
02839                 case QueueType::CallstackAlloc:
02840                 {
02841                     ThreadCtxCheckSerial( callstackAllocFatThread );
02842                     ptr = MemRead<uint64_t>( &item->callstackAllocFat.nativePtr );
02843                     if( ptr != 0 )
02844                     {
02845                         CutCallstack( (void*)ptr, "lua_pcall" );
02846                         SendCallstackPayload( ptr );
02847                         tracy_free_fast( (void*)ptr );
02848                     }
02849                     ptr = MemRead<uint64_t>( &item->callstackAllocFat.ptr );
02850                     SendCallstackAlloc( ptr );
02851                     tracy_free_fast( (void*)ptr );
02852                     break;
02853                 }
02854                 case QueueType::FiberEnter:
02855                 {
02856                     ThreadCtxCheckSerial( fiberEnter );
02857                     int64_t t = MemRead<int64_t>( &item->fiberEnter.time );
02858                     int64_t dt = t - refThread;
02859                     refThread = t;
02860                     MemWrite( &item->fiberEnter.time, dt );
02861                     break;
02862                 }
02863                 case QueueType::FiberLeave:
02864                 {
02865                     ThreadCtxCheckSerial( fiberLeave );
02866                     int64_t t = MemRead<int64_t>( &item->fiberLeave.time );
02867                     int64_t dt = t - refThread;
02868                     refThread = t;
02869                     MemWrite( &item->fiberLeave.time, dt );
02870                     break;
02871                 }
02872 #endif
02873                 default:
02874                     assert( false );
02875                     break;
02876                 }
02877             }
02878 #ifdef TRACY_FIBERS
02879             else
02880             {
02881                 switch( (QueueType)idx )
02882                 {
02883                 case QueueType::ZoneColor:
02884                 {
02885                     ThreadCtxCheckSerial( zoneColorThread );
02886                     break;
02887                 }
02888                 case QueueType::ZoneValue:
02889                 {
02890                     ThreadCtxCheckSerial( zoneValueThread );
02891                     break;
02892                 }
02893                 case QueueType::ZoneValidation:
02894                 {
02895                     ThreadCtxCheckSerial( zoneValidationThread );
02896                     break;
02897                 }
02898                 case QueueType::MessageLiteral:
02899                 case QueueType::MessageLiteralCallstack:
02900                 {
02901                     ThreadCtxCheckSerial( messageLiteralThread );
02902                     break;
02903                 }
02904                 case QueueType::MessageLiteralColor:
02905                 case QueueType::MessageLiteralColorCallstack:
02906                 {
02907                     ThreadCtxCheckSerial( messageColorLiteralThread );
02908                     break;
02909                 }
02910                 case QueueType::CrashReport:
02911                 {
02912                     ThreadCtxCheckSerial( crashReportThread );
02913                     break;
02914                 }
02915                 default:
02916                     break;
02917                 }
02918             }
02919 #endif
02920             if( !AppendData( item, QueueDataSize[idx] ) ) return DequeueStatus::ConnectionLost;
02921             item++;
02922         }
02923         m_refTimeSerial = refSerial;
02924         m_refTimeGpu = refGpu;
02925 #ifdef TRACY_FIBERS
02926         m_refTimeThread = refThread;
02927 #endif
02928         m_serialDequeue.clear();
02929     }
02930     else
02931     {
02932         return DequeueStatus::QueueEmpty;
02933     }
02934     return DequeueStatus::DataDequeued;
02935 }
