02937 Profiler::ThreadCtxStatus Profiler::ThreadCtxCheck( uint32_t threadId )
02938 {
02939     if( m_threadCtx == threadId ) return ThreadCtxStatus::Same;
02940     QueueItem item;
02941     MemWrite( &item.hdr.type, QueueType::ThreadContext );
02942     MemWrite( &item.threadCtx.thread, threadId );
02943     if( !AppendData( &item, QueueDataSize[(int)QueueType::ThreadContext] ) ) return ThreadCtxStatus::ConnectionLost;
02944     m_threadCtx = threadId;
02945     m_refTimeThread = 0;
02946     return ThreadCtxStatus::Changed;
02947 }
