02949 bool Profiler::CommitData()
02950 {
02951     bool ret = SendData( m_buffer + m_bufferStart, m_bufferOffset - m_bufferStart );
02952     if( m_bufferOffset > TargetFrameSize * 2 ) m_bufferOffset = 0;
02953     m_bufferStart = m_bufferOffset;
02954     return ret;
02955 }
