02957 bool Profiler::SendData( const char* data, size_t len )
02958 {
02959     const lz4sz_t lz4sz = LZ4_compress_fast_continue( (LZ4_stream_t*)m_stream, data, m_lz4Buf + sizeof( lz4sz_t ), (int)len, LZ4Size, 1 );
02960     memcpy( m_lz4Buf, &lz4sz, sizeof( lz4sz ) );
02961     return m_sock->Send( m_lz4Buf, lz4sz + sizeof( lz4sz_t ) ) != -1;
02962 }
