02964 void Profiler::SendString( uint64_t str, const char* ptr, size_t len, QueueType type )
02965 {
02966     assert( type == QueueType::StringData ||
02967             type == QueueType::ThreadName ||
02968             type == QueueType::PlotName ||
02969             type == QueueType::FrameName ||
02970             type == QueueType::ExternalName ||
02971             type == QueueType::ExternalThreadName ||
02972             type == QueueType::FiberName );
02973 
02974     QueueItem item;
02975     MemWrite( &item.hdr.type, type );
02976     MemWrite( &item.stringTransfer.ptr, str );
02977 
02978     assert( len <= std::numeric_limits<uint16_t>::max() );
02979     auto l16 = uint16_t( len );
02980 
02981     NeedDataSize( QueueDataSize[(int)type] + sizeof( l16 ) + l16 );
02982 
02983     AppendDataUnsafe( &item, QueueDataSize[(int)type] );
02984     AppendDataUnsafe( &l16, sizeof( l16 ) );
02985     AppendDataUnsafe( ptr, l16 );
02986 }
