03018 void Profiler::SendLongString( uint64_t str, const char* ptr, size_t len, QueueType type )
03019 {
03020     assert( type == QueueType::FrameImageData ||
03021             type == QueueType::SymbolCode ||
03022             type == QueueType::SourceCode );
03023 
03024     QueueItem item;
03025     MemWrite( &item.hdr.type, type );
03026     MemWrite( &item.stringTransfer.ptr, str );
03027 
03028     assert( len <= std::numeric_limits<uint32_t>::max() );
03029     assert( QueueDataSize[(int)type] + sizeof( uint32_t ) + len <= TargetFrameSize );
03030     auto l32 = uint32_t( len );
03031 
03032     NeedDataSize( QueueDataSize[(int)type] + sizeof( l32 ) + l32 );
03033 
