03039 void Profiler::SendSourceLocation( uint64_t ptr )
03040 {
03041     auto srcloc = (const SourceLocationData*)ptr;
03042     QueueItem item;
03043     MemWrite( &item.hdr.type, QueueType::SourceLocation );
03044     MemWrite( &item.srcloc.name, (uint64_t)srcloc->name );
03045     MemWrite( &item.srcloc.file, (uint64_t)srcloc->file );
03046     MemWrite( &item.srcloc.function, (uint64_t)srcloc->function );
03047     MemWrite( &item.srcloc.line, srcloc->line );
03048     MemWrite( &item.srcloc.b, uint8_t( ( srcloc->color       ) & 0xFF ) );
03049     MemWrite( &item.srcloc.g, uint8_t( ( srcloc->color >> 8  ) & 0xFF ) );
03050     MemWrite( &item.srcloc.r, uint8_t( ( srcloc->color >> 16 ) & 0xFF ) );
03051     AppendData( &item, QueueDataSize[(int)QueueType::SourceLocation] );
03052 }
03053 
03054 void Profiler::SendSourceLocationPayload( uint64_t _ptr )
03055 {
03056     auto ptr = (const char*)_ptr;
03057 
03058     QueueItem item;
03059     MemWrite( &item.hdr.type, QueueType::SourceLocationPayload );
03060     MemWrite( &item.stringTransfer.ptr, _ptr );
03061 
03062     uint16_t len;
03063     memcpy( &len, ptr, sizeof( len ) );
03064     assert( len > 2 );
03065     len -= 2;
03066     ptr += 2;
03067 
03068     NeedDataSize( QueueDataSize[(int)QueueType::SourceLocationPayload] + sizeof( len ) + len );
03069 
03070     AppendDataUnsafe( &item, QueueDataSize[(int)QueueType::SourceLocationPayload] );
03071     AppendDataUnsafe( &len, sizeof( len ) );
03072     AppendDataUnsafe( ptr, len );
03073 }
03074 
03075 void Profiler::SendCallstackPayload( uint64_t _ptr )
03076 {
03077     auto ptr = (uintptr_t*)_ptr;
03078 
03079     QueueItem item;
03080     MemWrite( &item.hdr.type, QueueType::CallstackPayload );
03081     MemWrite( &item.stringTransfer.ptr, _ptr );
03082 
03083     const auto sz = *ptr++;
03084     const auto len = sz * sizeof( uint64_t );
03085     const auto l16 = uint16_t( len );
03086 
03087     NeedDataSize( QueueDataSize[(int)QueueType::CallstackPayload] + sizeof( l16 ) + l16 );
03088 
03089     AppendDataUnsafe( &item, QueueDataSize[(int)QueueType::CallstackPayload] );
03090     AppendDataUnsafe( &l16, sizeof( l16 ) );
03091 
03092     if( compile_time_condition<sizeof( uintptr_t ) == sizeof( uint64_t )>::value )
03093     {
03094         AppendDataUnsafe( ptr, sizeof( uint64_t ) * sz );
03095     }
03096     else
03097     {
03098         for( uintptr_t i=0; i<sz; i++ )
03099         {
03100             const auto val = uint64_t( *ptr++ );
03101             AppendDataUnsafe( &val, sizeof( uint64_t ) );
03102         }
03103     }
03104 }
03105 
03106 void Profiler::SendCallstackPayload64( uint64_t _ptr )
03107 {
03108     auto ptr = (uint64_t*)_ptr;
03109 
03110     QueueItem item;
03111     MemWrite( &item.hdr.type, QueueType::CallstackPayload );
03112     MemWrite( &item.stringTransfer.ptr, _ptr );
03113 
03114     const auto sz = *ptr++;
03115     const auto len = sz * sizeof( uint64_t );
03116     const auto l16 = uint16_t( len );
03117 
03118     NeedDataSize( QueueDataSize[(int)QueueType::CallstackPayload] + sizeof( l16 ) + l16 );
03119 
03120     AppendDataUnsafe( &item, QueueDataSize[(int)QueueType::CallstackPayload] );
03121     AppendDataUnsafe( &l16, sizeof( l16 ) );
03122     AppendDataUnsafe( ptr, sizeof( uint64_t ) * sz );
03123 }
