03201 #ifdef TRACY_HAS_CALLSTACK
03202 void Profiler::HandleSymbolQueueItem( const SymbolQueueItem& si )
03203 {
03204     switch( si.type )
03205     {
03206     case SymbolQueueItemType::CallstackFrame:
03207     {
03208         const auto frameData = DecodeCallstackPtr( si.ptr );
03209         auto data = tracy_malloc_fast( sizeof( CallstackEntry ) * frameData.size );
03210         memcpy( data, frameData.data, sizeof( CallstackEntry ) * frameData.size );
03211         TracyLfqPrepare( QueueType::CallstackFrameSize );
03212         MemWrite( &item->callstackFrameSizeFat.ptr, si.ptr );
03213         MemWrite( &item->callstackFrameSizeFat.size, frameData.size );
03214         MemWrite( &item->callstackFrameSizeFat.data, (uint64_t)data );
03215         MemWrite( &item->callstackFrameSizeFat.imageName, (uint64_t)frameData.imageName );
03216         TracyLfqCommit;
03217         break;
03218     }
03219     case SymbolQueueItemType::SymbolQuery:
03220     {
03221 #ifdef __ANDROID__
03222         // On Android it's common for code to be in mappings that are only executable
03223         // but not readable.
03224         if( !EnsureReadable( si.ptr ) )
03225         {
03226             TracyLfqPrepare( QueueType::AckServerQueryNoop );
03227             TracyLfqCommit;
03228             break;
03229         }
03230 #endif
03231         const auto sym = DecodeSymbolAddress( si.ptr );
03232         TracyLfqPrepare( QueueType::SymbolInformation );
03233         MemWrite( &item->symbolInformationFat.line, sym.line );
03234         MemWrite( &item->symbolInformationFat.symAddr, si.ptr );
03235         MemWrite( &item->symbolInformationFat.fileString, (uint64_t)sym.file );
03236         MemWrite( &item->symbolInformationFat.needFree, (uint8_t)sym.needFree );
03237         TracyLfqCommit;
03238         break;
03239     }
03240 #ifdef TRACY_HAS_SYSTEM_TRACING
03241     case SymbolQueueItemType::ExternalName:
03242     {
03243         const char* threadName;
03244         const char* name;
03245         SysTraceGetExternalName( si.ptr, threadName, name );
03246         TracyLfqPrepare( QueueType::ExternalNameMetadata );
03247         MemWrite( &item->externalNameMetadata.thread, si.ptr );
03248         MemWrite( &item->externalNameMetadata.name, (uint64_t)name );
03249         MemWrite( &item->externalNameMetadata.threadName, (uint64_t)threadName );
03250         TracyLfqCommit;
03251         break;
03252     }
03253 #endif
03254     case SymbolQueueItemType::KernelCode:
03255     {
03256 #ifdef _WIN32
03257         auto mod = GetKernelModulePath( si.ptr );
03258         if( mod )
03259         {
03260             auto fn = DecodeCallstackPtrFast( si.ptr );
03261             if( *fn )
03262             {
03263                 auto hnd = LoadLibraryExA( mod, nullptr, DONT_RESOLVE_DLL_REFERENCES );
03264                 if( hnd )
03265                 {
03266                     auto ptr = (const void*)GetProcAddress( hnd, fn );
03267                     if( ptr )
03268                     {
03269                         auto buf = (char*)tracy_malloc( si.extra );
03270                         memcpy( buf, ptr, si.extra );
03271                         FreeLibrary( hnd );
03272                         TracyLfqPrepare( QueueType::SymbolCodeMetadata );
03273                         MemWrite( &item->symbolCodeMetadata.symbol, si.ptr );
03274                         MemWrite( &item->symbolCodeMetadata.ptr, (uint64_t)buf );
03275                         MemWrite( &item->symbolCodeMetadata.size, (uint32_t)si.extra );
03276                         TracyLfqCommit;
03277                         break;
03278                     }
03279                     FreeLibrary( hnd );
03280                 }
03281             }
03282         }
03283 #endif
03284         TracyLfqPrepare( QueueType::AckSymbolCodeNotAvailable );
03285         TracyLfqCommit;
03286         break;
03287     }
03288     case SymbolQueueItemType::SourceCode:
03289         HandleSourceCodeQuery( (char*)si.ptr, (char*)si.extra, si.id );
03290         break;
03291     default:
03292         assert( false );
03293         break;
03294     }
03295 }
03296 
03297 void Profiler::SymbolWorker()
03298 {
03299 #if defined __linux__ && !defined TRACY_NO_CRASH_HANDLER
03300     s_symbolTid = syscall( SYS_gettid );
03301 #endif
03302 
03303     ThreadExitHandler threadExitHandler;
03304     SetThreadName( "Tracy Symbol Worker" );
03305 #ifdef TRACY_USE_RPMALLOC
03306     InitRpmalloc();
03307 #endif
03308     InitCallstack();
03309     while( m_timeBegin.load( std::memory_order_relaxed ) == 0 ) std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) );
03310 
03311     for(;;)
03312     {
03313         const auto shouldExit = ShouldExit();
03314 #ifdef TRACY_ON_DEMAND
03315         if( !IsConnected() )
03316         {
03317             if( shouldExit )
03318             {
03319                 s_symbolThreadGone.store( true, std::memory_order_release );
03320                 return;
03321             }
03322             while( m_symbolQueue.front() ) m_symbolQueue.pop();
03323             std::this_thread::sleep_for( std::chrono::milliseconds( 20 ) );
03324             continue;
03325         }
03326 #endif
03327         auto si = m_symbolQueue.front();
03328         if( si )
03329         {
03330             HandleSymbolQueueItem( *si );
03331             m_symbolQueue.pop();
03332         }
03333         else
03334         {
03335             if( shouldExit )
03336             {
03337                 s_symbolThreadGone.store( true, std::memory_order_release );
03338                 return;
03339             }
03340             std::this_thread::sleep_for( std::chrono::milliseconds( 20 ) );
03341         }
03342     }
03343 }
03344 #endif
03345 
03346 bool Profiler::HandleServerQuery()
03347 {
03348     ServerQueryPacket payload;
03349     if( !m_sock->Read( &payload, sizeof( payload ), 10 ) ) return false;
03350 
03351     uint8_t type;
03352     uint64_t ptr;
03353     memcpy( &type, &payload.type, sizeof( payload.type ) );
03354     memcpy( &ptr, &payload.ptr, sizeof( payload.ptr ) );
03355 
03356     switch( type )
03357     {
03358     case ServerQueryString:
03359         SendString( ptr, (const char*)ptr, QueueType::StringData );
03360         break;
03361     case ServerQueryThreadString:
03362         if( ptr == m_mainThread )
03363         {
03364             SendString( ptr, "Main thread", 11, QueueType::ThreadName );
03365         }
03366         else
03367         {
03368             SendString( ptr, GetThreadName( ptr ), QueueType::ThreadName );
03369         }
03370         break;
03371     case ServerQuerySourceLocation:
03372         SendSourceLocation( ptr );
03373         break;
03374     case ServerQueryPlotName:
03375         SendString( ptr, (const char*)ptr, QueueType::PlotName );
03376         break;
03377     case ServerQueryTerminate:
03378         return false;
03379     case ServerQueryCallstackFrame:
03380         QueueCallstackFrame( ptr );
03381         break;
03382     case ServerQueryFrameName:
03383         SendString( ptr, (const char*)ptr, QueueType::FrameName );
03384         break;
03385     case ServerQueryDisconnect:
03386         HandleDisconnect();
03387         return false;
03388 #ifdef TRACY_HAS_SYSTEM_TRACING
03389     case ServerQueryExternalName:
03390         QueueExternalName( ptr );
03391         break;
03392 #endif
03393     case ServerQueryParameter:
03394         HandleParameter( ptr );
03395         break;
03396     case ServerQuerySymbol:
03397         QueueSymbolQuery( ptr );
03398         break;
03399 #ifndef TRACY_NO_CODE_TRANSFER
03400     case ServerQuerySymbolCode:
03401         HandleSymbolCodeQuery( ptr, payload.extra );
03402         break;
03403 #endif
03404     case ServerQuerySourceCode:
03405         QueueSourceCodeQuery( uint32_t( ptr ) );
03406         break;
03407     case ServerQueryDataTransfer:
03408         if( m_queryData )
03409         {
03410             assert( !m_queryImage );
03411             m_queryImage = m_queryData;
03412         }
03413         m_queryDataPtr = m_queryData = (char*)tracy_malloc( ptr + 11 );
03414         AckServerQuery();
03415         break;
03416     case ServerQueryDataTransferPart:
03417         memcpy( m_queryDataPtr, &ptr, 8 );
03418         memcpy( m_queryDataPtr+8, &payload.extra, 4 );
03419         m_queryDataPtr += 12;
03420         AckServerQuery();
03421         break;
03422 #ifdef TRACY_FIBERS
03423     case ServerQueryFiberName:
03424         SendString( ptr, (const char*)ptr, QueueType::FiberName );
03425         break;
03426 #endif
03427     default:
03428         assert( false );
03429         break;
03430     }
03431 
03432     return true;
03433 }
03434 
03435 void Profiler::HandleDisconnect()
03436 {
03437     moodycamel::ConsumerToken token( GetQueue() );
03438 
03439 #ifdef TRACY_HAS_SYSTEM_TRACING
03440     if( s_sysTraceThread )
03441     {
03442         auto timestamp = GetTime();
03443         for(;;)
03444         {
03445             const auto status = DequeueContextSwitches( token, timestamp );
03446             if( status == DequeueStatus::ConnectionLost )
03447             {
03448                 return;
03449             }
03450             else if( status == DequeueStatus::QueueEmpty )
03451             {
03452                 if( m_bufferOffset != m_bufferStart )
03453                 {
03454                     if( !CommitData() ) return;
03455                 }
03456             }
03457             if( timestamp < 0 )
03458             {
03459                 if( m_bufferOffset != m_bufferStart )
03460                 {
03461                     if( !CommitData() ) return;
03462                 }
03463                 break;
03464             }
03465             ClearSerial();
03466             if( m_sock->HasData() )
03467             {
03468                 while( m_sock->HasData() )
03469                 {
03470                     if( !HandleServerQuery() ) return;
03471                 }
03472                 if( m_bufferOffset != m_bufferStart )
03473                 {
03474                     if( !CommitData() ) return;
03475                 }
03476             }
03477             else
03478             {
03479                 if( m_bufferOffset != m_bufferStart )
03480                 {
03481                     if( !CommitData() ) return;
03482                 }
03483                 std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) );
03484             }
03485         }
03486     }
03487 #endif
03488 
03489     QueueItem terminate;
03490     MemWrite( &terminate.hdr.type, QueueType::Terminate );
03491     if( !SendData( (const char*)&terminate, 1 ) ) return;
03492     for(;;)
03493     {
03494         ClearQueues( token );
03495         if( m_sock->HasData() )
03496         {
03497             while( m_sock->HasData() )
03498             {
03499                 if( !HandleServerQuery() ) return;
03500             }
03501             if( m_bufferOffset != m_bufferStart )
03502             {
03503                 if( !CommitData() ) return;
03504             }
03505         }
03506         else
03507         {
03508             if( m_bufferOffset != m_bufferStart )
03509             {
03510                 if( !CommitData() ) return;
03511             }
03512             std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) );
03513         }
03514     }
03515 }
03516 
03517 void Profiler::CalibrateTimer()
03518 {
03519     m_timerMul = 1.;
03520 
03521 #ifdef TRACY_HW_TIMER
03522 
03523 #  if !defined TRACY_TIMER_QPC && defined TRACY_TIMER_FALLBACK
03524     const bool needCalibration = HardwareSupportsInvariantTSC();
03525 #  else
03526     const bool needCalibration = true;
03527 #  endif
03528     if( needCalibration )
03529     {
03530         std::atomic_signal_fence( std::memory_order_acq_rel );
03531         const auto t0 = std::chrono::high_resolution_clock::now();
03532         const auto r0 = GetTime();
03533         std::atomic_signal_fence( std::memory_order_acq_rel );
03534         std::this_thread::sleep_for( std::chrono::milliseconds( 200 ) );
03535         std::atomic_signal_fence( std::memory_order_acq_rel );
03536         const auto t1 = std::chrono::high_resolution_clock::now();
03537         const auto r1 = GetTime();
03538         std::atomic_signal_fence( std::memory_order_acq_rel );
03539 
03540         const auto dt = std::chrono::duration_cast<std::chrono::nanoseconds>( t1 - t0 ).count();
03541         const auto dr = r1 - r0;
03542 
03543         m_timerMul = double( dt ) / double( dr );
03544     }
03545 #endif
03546 }
03547 
03548 void Profiler::CalibrateDelay()
03549 {
03550     constexpr int Iterations = 50000;
03551 
03552     auto mindiff = std::numeric_limits<int64_t>::max();
03553     for( int i=0; i<Iterations * 10; i++ )
03554     {
03555         const auto t0i = GetTime();
03556         const auto t1i = GetTime();
03557         const auto dti = t1i - t0i;
03558         if( dti > 0 && dti < mindiff ) mindiff = dti;
03559     }
03560     m_resolution = mindiff;
03561 
03562 #ifdef TRACY_DELAYED_INIT
03563     m_delay = m_resolution;
03564 #else
03565     constexpr int Events = Iterations * 2;   // start + end
03566     static_assert( Events < QueuePrealloc, "Delay calibration loop will allocate memory in queue" );
03567 
03568     static const tracy::SourceLocationData __tracy_source_location { nullptr, TracyFunction,  TracyFile, (uint32_t)TracyLine, 0 };
03569     const auto t0 = GetTime();
03570     for( int i=0; i<Iterations; i++ )
03571     {
03572         {
03573             TracyLfqPrepare( QueueType::ZoneBegin );
03574             MemWrite( &item->zoneBegin.time, Profiler::GetTime() );
03575             MemWrite( &item->zoneBegin.srcloc, (uint64_t)&__tracy_source_location );
03576             TracyLfqCommit;
03577         }
03578         {
03579             TracyLfqPrepare( QueueType::ZoneEnd );
03580             MemWrite( &item->zoneEnd.time, GetTime() );
03581             TracyLfqCommit;
03582         }
03583     }
03584     const auto t1 = GetTime();
03585     const auto dt = t1 - t0;
03586     m_delay = dt / Events;
03587 
03588     moodycamel::ConsumerToken token( GetQueue() );
03589     int left = Events;
03590     while( left != 0 )
03591     {
03592         const auto sz = GetQueue().try_dequeue_bulk_single( token, [](const uint64_t&){}, [](QueueItem* item, size_t sz){} );
03593         assert( sz > 0 );
03594         left -= (int)sz;
03595     }
03596     assert( GetQueue().size_approx() == 0 );
03597 #endif
03598 }
03599 
03600 void Profiler::ReportTopology()
03601 {
03602 #ifndef TRACY_DELAYED_INIT
03603     struct CpuData
03604     {
03605         uint32_t package;
03606         uint32_t core;
03607         uint32_t thread;
03608     };
03609 
03610 #if defined _WIN32
03611 #  ifdef TRACY_UWP
03612     t_GetLogicalProcessorInformationEx _GetLogicalProcessorInformationEx = &::GetLogicalProcessorInformationEx;
03613 #  else
03614     t_GetLogicalProcessorInformationEx _GetLogicalProcessorInformationEx = (t_GetLogicalProcessorInformationEx)GetProcAddress( GetModuleHandleA( "kernel32.dll" ), "GetLogicalProcessorInformationEx" );
03615 #  endif
03616     if( !_GetLogicalProcessorInformationEx ) return;
03617 
03618     DWORD psz = 0;
03619     _GetLogicalProcessorInformationEx( RelationProcessorPackage, nullptr, &psz );
03620     auto packageInfo = (SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX*)tracy_malloc( psz );
03621     auto res = _GetLogicalProcessorInformationEx( RelationProcessorPackage, packageInfo, &psz );
03622     assert( res );
03623 
03624     DWORD csz = 0;
03625     _GetLogicalProcessorInformationEx( RelationProcessorCore, nullptr, &csz );
03626     auto coreInfo = (SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX*)tracy_malloc( csz );
03627     res = _GetLogicalProcessorInformationEx( RelationProcessorCore, coreInfo, &csz );
03628     assert( res );
03629 
03630     SYSTEM_INFO sysinfo;
03631     GetSystemInfo( &sysinfo );
03632     const uint32_t numcpus = sysinfo.dwNumberOfProcessors;
03633 
03634     auto cpuData = (CpuData*)tracy_malloc( sizeof( CpuData ) * numcpus );
03635     for( uint32_t i=0; i<numcpus; i++ ) cpuData[i].thread = i;
03636 
03637     int idx = 0;
03638     auto ptr = packageInfo;
03639     while( (char*)ptr < ((char*)packageInfo) + psz )
03640     {
03641         assert( ptr->Relationship == RelationProcessorPackage );
03642         // FIXME account for GroupCount
03643         auto mask = ptr->Processor.GroupMask[0].Mask;
03644         int core = 0;
03645         while( mask != 0 )
03646         {
03647             if( mask & 1 ) cpuData[core].package = idx;
03648             core++;
03649             mask >>= 1;
03650         }
03651         ptr = (SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX*)(((char*)ptr) + ptr->Size);
03652         idx++;
03653     }
03654 
03655     idx = 0;
03656     ptr = coreInfo;
03657     while( (char*)ptr < ((char*)coreInfo) + csz )
03658     {
03659         assert( ptr->Relationship == RelationProcessorCore );
03660         // FIXME account for GroupCount
03661         auto mask = ptr->Processor.GroupMask[0].Mask;
03662         int core = 0;
03663         while( mask != 0 )
03664         {
03665             if( mask & 1 ) cpuData[core].core = idx;
03666             core++;
03667             mask >>= 1;
03668         }
03669         ptr = (SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX*)(((char*)ptr) + ptr->Size);
03670         idx++;
03671     }
03672 
03673     for( uint32_t i=0; i<numcpus; i++ )
03674     {
03675         auto& data = cpuData[i];
03676 
03677         TracyLfqPrepare( QueueType::CpuTopology );
03678         MemWrite( &item->cpuTopology.package, data.package );
03679         MemWrite( &item->cpuTopology.core, data.core );
03680         MemWrite( &item->cpuTopology.thread, data.thread );
03681 
03682 #ifdef TRACY_ON_DEMAND
03683         DeferItem( *item );
03684 #endif
03685 
03686         TracyLfqCommit;
03687     }
03688 
03689     tracy_free( cpuData );
03690     tracy_free( coreInfo );
03691     tracy_free( packageInfo );
03692 #elif defined __linux__
03693     const int numcpus = std::thread::hardware_concurrency();
03694     auto cpuData = (CpuData*)tracy_malloc( sizeof( CpuData ) * numcpus );
03695     memset( cpuData, 0, sizeof( CpuData ) * numcpus );
03696 
03697     const char* basePath = "/sys/devices/system/cpu/cpu";
03698     for( int i=0; i<numcpus; i++ )
03699     {
03700         char path[1024];
03701         sprintf( path, "%s%i/topology/physical_package_id", basePath, i );
03702         char buf[1024];
03703         FILE* f = fopen( path, "rb" );
03704         if( !f )
03705         {
03706             tracy_free( cpuData );
03707             return;
03708         }
03709         auto read = fread( buf, 1, 1024, f );
03710         buf[read] = '\0';
03711         fclose( f );
03712         cpuData[i].package = uint32_t( atoi( buf ) );
03713         cpuData[i].thread = i;
03714         sprintf( path, "%s%i/topology/core_id", basePath, i );
03715         f = fopen( path, "rb" );
03716         read = fread( buf, 1, 1024, f );
03717         buf[read] = '\0';
03718         fclose( f );
03719         cpuData[i].core = uint32_t( atoi( buf ) );
03720     }
03721 
03722     for( int i=0; i<numcpus; i++ )
03723     {
03724         auto& data = cpuData[i];
03725 
03726         TracyLfqPrepare( QueueType::CpuTopology );
03727         MemWrite( &item->cpuTopology.package, data.package );
03728         MemWrite( &item->cpuTopology.core, data.core );
03729         MemWrite( &item->cpuTopology.thread, data.thread );
03730 
03731 #ifdef TRACY_ON_DEMAND
03732         DeferItem( *item );
03733 #endif
03734 
03735         TracyLfqCommit;
03736     }
03737 
03738     tracy_free( cpuData );
03739 #endif
03740 #endif
03741 }
03742 
03743 void Profiler::SendCallstack( int depth, const char* skipBefore )
03744 {
03745 #ifdef TRACY_HAS_CALLSTACK
03746     auto ptr = Callstack( depth );
03747     CutCallstack( ptr, skipBefore );
03748 
03749     TracyQueuePrepare( QueueType::Callstack );
03750     MemWrite( &item->callstackFat.ptr, (uint64_t)ptr );
03751     TracyQueueCommit( callstackFatThread );
03752 #endif
03753 }
03754 
03755 void Profiler::CutCallstack( void* callstack, const char* skipBefore )
03756 {
03757 #ifdef TRACY_HAS_CALLSTACK
03758     auto data = (uintptr_t*)callstack;
03759     const auto sz = *data++;
03760     uintptr_t i;
03761     for( i=0; i<sz; i++ )
03762     {
03763         auto name = DecodeCallstackPtrFast( uint64_t( data[i] ) );
03764         const bool found = strcmp( name, skipBefore ) == 0;
03765         if( found )
03766         {
03767             i++;
03768             break;
03769         }
03770     }
03771 
03772     if( i != sz )
03773     {
03774         memmove( data, data + i, ( sz - i ) * sizeof( uintptr_t* ) );
03775         *--data = sz - i;
03776     }
03777 #endif
03778 }
