03780 #ifdef TRACY_HAS_SYSTIME
03781 void Profiler::ProcessSysTime()
03782 {
03783     if( m_shutdown.load( std::memory_order_relaxed ) ) return;
03784     auto t = std::chrono::high_resolution_clock::now().time_since_epoch().count();
03785     if( t - m_sysTimeLast > 100000000 )    // 100 ms
03786     {
03787         auto sysTime = m_sysTime.Get();
03788         if( sysTime >= 0 )
03789         {
03790             m_sysTimeLast = t;
03791 
03792             TracyLfqPrepare( QueueType::SysTimeReport );
03793             MemWrite( &item->sysTime.time, GetTime() );
03794             MemWrite( &item->sysTime.sysTime, sysTime );
03795             TracyLfqCommit;
03796         }
03797     }
03798 }
03799 #endif
