03810 void Profiler::HandleSymbolCodeQuery( uint64_t symbol, uint32_t size )
03811 {
03812     if( symbol >> 63 != 0 )
03813     {
03814         QueueKernelCode( symbol, size );
03815     }
03816     else
03817     {
03818 #ifdef __ANDROID__
03819         // On Android it's common for code to be in mappings that are only executable
03820         // but not readable.
03821         if( !EnsureReadable( symbol ) )
03822         {
03823             AckSymbolCodeNotAvailable();
03824             return;
03825         }
03826 #endif
03827         SendLongString( symbol, (const char*)symbol, size, QueueType::SymbolCode );
03828     }
03829 }
03830 
03831 void Profiler::HandleSourceCodeQuery( char* data, char* image, uint32_t id )
03832 {
03833     bool ok = false;
03834     struct stat st;
03835     if( stat( data, &st ) == 0 && (uint64_t)st.st_mtime < m_exectime )
03836     {
03837         if( st.st_size < ( TargetFrameSize - 16 ) )
03838         {
03839             FILE* f = fopen( data, "rb" );
03840             if( f )
03841             {
03842                 auto ptr = (char*)tracy_malloc_fast( st.st_size );
03843                 auto rd = fread( ptr, 1, st.st_size, f );
03844                 fclose( f );
03845                 if( rd == (size_t)st.st_size )
03846                 {
03847                     TracyLfqPrepare( QueueType::SourceCodeMetadata );
03848                     MemWrite( &item->sourceCodeMetadata.ptr, (uint64_t)ptr );
03849                     MemWrite( &item->sourceCodeMetadata.size, (uint32_t)rd );
03850                     MemWrite( &item->sourceCodeMetadata.id, id );
03851                     TracyLfqCommit;
03852                     ok = true;
03853                 }
03854             }
03855         }
03856     }
03857 
03858 #ifdef TRACY_DEBUGINFOD
03859     else if( image && data[0] == '/' )
03860     {
03861         size_t size;
03862         auto buildid = GetBuildIdForImage( image, size );
03863         if( buildid )
03864         {
03865             auto d = debuginfod_find_source( GetDebuginfodClient(), buildid, size, data, nullptr );
03866             TracyDebug( "DebugInfo source query: %s, fn: %s, image: %s\n", d >= 0 ? " ok " : "fail", data, image );
03867             if( d >= 0 )
03868             {
03869                 struct stat st;
03870                 fstat( d, &st );
03871                 if( st.st_size < ( TargetFrameSize - 16 ) )
03872                 {
03873                     lseek( d, 0, SEEK_SET );
03874                     auto ptr = (char*)tracy_malloc_fast( st.st_size );
03875                     auto rd = read( d, ptr, st.st_size );
03876                     if( rd == (size_t)st.st_size )
03877                     {
03878                         TracyLfqPrepare( QueueType::SourceCodeMetadata );
03879                         MemWrite( &item->sourceCodeMetadata.ptr, (uint64_t)ptr );
03880                         MemWrite( &item->sourceCodeMetadata.size, (uint32_t)rd );
03881                         MemWrite( &item->sourceCodeMetadata.id, id );
03882                         TracyLfqCommit;
03883                         ok = true;
03884                     }
03885                 }
03886                 close( d );
03887             }
03888         }
03889     }
03890     else
03891     {
03892         TracyDebug( "DebugInfo invalid query fn: %s, image: %s\n", data, image );
03893     }
03894 #endif
03895 
03896     if( !ok && m_sourceCallback )
03897     {
03898         size_t sz;
03899         char* ptr = m_sourceCallback( m_sourceCallbackData, data, sz );
03900         if( ptr )
03901         {
03902             if( sz < ( TargetFrameSize - 16 ) )
03903             {
03904                 TracyLfqPrepare( QueueType::SourceCodeMetadata );
03905                 MemWrite( &item->sourceCodeMetadata.ptr, (uint64_t)ptr );
03906                 MemWrite( &item->sourceCodeMetadata.size, (uint32_t)sz );
03907                 MemWrite( &item->sourceCodeMetadata.id, id );
03908                 TracyLfqCommit;
03909                 ok = true;
03910             }
03911         }
03912     }
03913 
03914     if( !ok )
03915     {
03916         TracyLfqPrepare( QueueType::AckSourceCodeNotAvailable );
03917         MemWrite( &item->sourceCodeNotAvailable, id );
03918         TracyLfqCommit;
03919     }
03920 
03921     tracy_free_fast( data );
03922     tracy_free_fast( image );
03923 }
